insert into woerter (slug, wort, artikel, ipa, wortart, kategorie, definition, bedeutungen, beispiel) values
  ('untahoitsvoaschuss', 'Untahoitsvoaschuss', '', '', '', '', 'Unterhaltsvorschuss', '[{"kategorie": "jur.", "text": "\"staatliche Leistung, die in Österreich gewährt wird, wenn ein unterhaltsberechtigtes Kind keinen oder nur unzureichenden Unterhalt von dem unterhaltspflichtigen Elternteil erhält\""}, {"kategorie": "", "text": "Der Staat springt in solchen Fällen ein und zahlt dem Kind einen Vorschuss auf den Unterhalt, um dessen Lebensunterhalt sicherzustellen"}, {"kategorie": "", "text": "Diese Leistung soll sicherstellen, dass Kinder, die Anspruch auf Unterhalt haben, nicht ohne finanzielle Unterstützung bleiben, wenn der unterhaltspflichtige Elternteil seiner Zahlungsverpflichtung nicht nachkommt"}, {"kategorie": "", "text": "In der Regel muss zuvor ein rechtskräftiger [[Unterhaltstitel]] (z. B. ein [[Gerichtsurteil]] oder eine Vereinbarung) vorliegen, der die Höhe des Unterhaltsanspruchs festlegt"}, {"kategorie": "", "text": "Der Unterhaltsvorschuss wird auf Antrag gewährt. Der Antrag kann in Österreich beim zuständigen [[Bezirksgericht]] oder bei der zuständigen Behörde gestellt werden, meist durch den Elternteil, bei dem das Kind lebt"}, {"kategorie": "", "text": "Der Staat zahlt den Unterhalt bis zu einer bestimmten Höhe als Vorschuss an das Kind bzw. dessen betreuenden Elternteil. Der genaue Betrag richtet sich nach dem festgesetzten Unterhaltsanspruch"}, {"kategorie": "", "text": "Der Staat tritt in Vorleistung und fordert anschließend den gezahlten Unterhaltsvorschuss vom unterhaltspflichtigen Elternteil (dem Unterhaltsschuldner) zurück. Falls dieser nicht zahlungsfähig ist, trägt der Staat das finanzielle Risiko"}, {"kategorie": "", "text": "Der Unterhaltsvorschuss wird für minderjährige Kinder oder junge Erwachsene gewährt, die einen Anspruch auf Unterhalt haben, aber keinen oder unzureichenden Unterhalt erhalten. Es kann auch für volljährige Kinder bis zu einem bestimmten Alter (z. B. während einer Ausbildung) beantragt werden"}, {"kategorie": "", "text": "Der Unterhaltsvorschuss dient dem Schutz des Kindeswohls, indem er sicherstellt, dass das Kind auch dann finanzielle Unterstützung erhält, wenn der unterhaltspflichtige Elternteil zahlungsunfähig oder -unwillig ist."}]'::jsonb, ''),
  ('maanvafoan', 'Maanvafoan', '', '', '', '', 'Mahnverfahren', '[{"kategorie": "jur.", "text": "\"vereinfachtes, gerichtliches Verfahren zur schnellen und kostengünstigen Durchsetzung von unbestrittenen Geldforderungen\""}, {"kategorie": "", "text": "Es wird genutzt, wenn der Gläubiger eine Geldforderung gegenüber einem Schuldner geltend machen möchte, ohne sofort ein langwieriges [[Gerichtsverfahren]] einzuleiten"}, {"kategorie": "", "text": "Ziel des Mahnverfahrens ist es, den Schuldner zur Zahlung zu bewegen und ihm die Möglichkeit zu geben, entweder die Forderung anzuerkennen oder [[Widerspruch]] einzulegen"}, {"kategorie": "", "text": "Im Mahnverfahren wird eine Forderung ohne eine umfangreiche gerichtliche Prüfung geltend gemacht. Der Gläubiger kann das Verfahren einleiten, indem er beim zuständigen [[Gericht]] einen [[Mahnbescheid]] beantragt"}, {"kategorie": "", "text": "Der Gläubiger stellt beim Gericht einen Antrag auf Erlass eines Mahnbescheids. Der Antrag enthält die Forderungssumme und die Begründung, warum der Schuldner in Verzug ist"}, {"kategorie": "", "text": "Das Gericht erlässt den [[Mahnbescheid]], der dem Schuldner zugestellt wird. Mit dem Mahnbescheid wird der Schuldner aufgefordert, die Forderung innerhalb einer bestimmten Frist (in der Regel 14 Tage) zu begleichen oder [[Widerspruch]] einzulegen"}, {"kategorie": "", "text": "Der Schuldner hat die Möglichkeit, innerhalb der gesetzlichen Frist Widerspruch gegen den Mahnbescheid einzulegen, wenn er die Forderung bestreitet. In diesem Fall wird das Mahnverfahren in ein reguläres [[Gerichtsverfahren]] überführt, bei dem die Rechtmäßigkeit der Forderung geprüft wird"}, {"kategorie": "", "text": "Wenn der Schuldner nicht zahlt und keinen Widerspruch einlegt, kann der Gläubiger nach Ablauf der Frist beim Gericht einen [[Vollstreckungsbescheid]] beantragen. Dieser ist Grundlage für die Einleitung der [[Zwangsvollstreckung]], mit der der Gläubiger seine Forderung durchsetzen kann."}]'::jsonb, ''),
  ('maanbescheid', 'Maanbescheid', '', '', '', '', 'Mahnbescheid', '[{"kategorie": "jur.", "text": "gerichtliche Anordnung im Rahmen eines vereinfachten [[Mahnverfahrens]], mit welcher der [[Gläubiger]] eine Forderung gegen einen [[Schuldner]] geltend machen kann, ohne ein reguläres [[Gerichtsverfahren]] einzuleiten"}, {"kategorie": "", "text": "Der Mahnbescheid dient dazu, den Schuldner zur Zahlung einer offenen Geldforderung aufzufordern und ihm die Möglichkeit zu geben, entweder die Forderung zu begleichen oder [[Widerspruch]] einzulegen"}, {"kategorie": "", "text": "Wird der Mahnbescheid vom Schuldner nicht angefochten, kann der Gläubiger anschließend einenà Vollstreckungsbescheid erwirken und die [[Zwangsvollstreckung]] einleiten"}, {"kategorie": "", "text": "Der Mahnbescheid ist ein schnelles und effizientes Mittel für Gläubiger, um unbestrittene Forderungen geltend zu machen, ohne sofort ein kostenintensives Gerichtsverfahren führen zu müssen."}]'::jsonb, ''),
  ('existenzminimum', 'Existenzminimum', '', '', '', '', 'Existenzminimum', '[{"kategorie": "jur.", "text": "\"Betrag, der einer Person nach gesetzlichen Regelungen zur Deckung ihrer grundlegenden Lebensbedürfnisse verbleiben muss, insbesondere in Fällen von [[Pfändungen]] oder bei der Berechnung von Unterhaltszahlungen\""}, {"kategorie": "", "text": "Das Existenzminimum soll die Grundbedürfnisse des Schuldners oder Unterhaltspflichtigen abdecken, darunter Kosten für Wohnung, Nahrung, Kleidung, medizinische Versorgung und andere alltägliche Ausgaben"}, {"kategorie": "", "text": "Bei [[Lohn-]] oder [[Kontopfändungen]] schützt das Existenzminimum den [[Schuldner]] vor völliger Verarmung. Ein bestimmter Betrag des Einkommens bleibt unpfändbar und muss dem Schuldner erhalten bleiben. Dieser Betrag richtet sich nach gesetzlichen [[Pfändungsfreigrenzen]], die auch von der Anzahl der unterhaltsberechtigten Personen abhängen"}, {"kategorie": "", "text": "Im Unterhaltsrecht wird das Existenzminimum bei der Berechnung der Höhe von Unterhaltszahlungen berücksichtigt, um sicherzustellen, dass der Unterhaltspflichtige nach der Leistung von Unterhalt genug Mittel für den eigenen Lebensunterhalt behält"}, {"kategorie": "", "text": "Das Existenzminimum wird regelmäßig an die wirtschaftlichen Bedingungen und die Lebenshaltungskosten angepasst, um sicherzustellen, dass es den aktuellen Anforderungen für ein menschenwürdiges Leben entspricht"}, {"kategorie": "", "text": "Das Existenzminimum ist im österreichischen Pfändungsrecht und Unterhaltsrecht gesetzlich geregelt. Es dient dazu, einen sozialen Ausgleich zu schaffen und sicherzustellen, dass Schuldner trotz Schulden ein menschenwürdiges Leben führen können."}]'::jsonb, ''),
  ('voischdreckungsgericht', 'Voischdreckungsgericht', '', '', '', '', 'Vollstreckungsgericht', '[{"kategorie": "jur.", "text": "\"Gericht, das für die Durchführung von [[Zwangsvollstreckungsmaßnahmen]] zuständig ist\""}, {"kategorie": "", "text": "Es sorgt dafür, dass rechtskräftige [[Urteile]] und andere [[vollstreckbare]] Titel, wie [[Vollstreckungsbescheide]] oder notarielle Urkunden, durchgesetzt werden, wenn der [[Schuldner]] seiner Verpflichtung nicht freiwillig nachkommt"}, {"kategorie": "", "text": "Das Vollstreckungsgericht überwacht den Prozess der Zwangsvollstreckung und stellt sicher, dass die Rechte sowohl des Gläubigers als auch des Schuldners gewahrt werden"}, {"kategorie": "", "text": "Wichtige Aufgaben des Vollstreckungsgerichts:  (i) Erlass von [[Pfändungs-]] und Überweisungsbeschlüssen: Diese ermöglichen es dem Gläubiger, das Vermögen des Schuldners zu pfänden, sei es durch [[Lohnpfändung]], [[Kontopfändung]] oder [[Sachpfändung]];  (ii) Anordnung von Zwangsvollstreckungsmaßnahmen: Das Vollstreckungsgericht leitet Maßnahmen ein, um eine Forderung des Gläubigers durch Zwangsvollstreckung durchzusetzen. Es entscheidet über den Antrag des Gläubigers und ordnet die Durchführung an, z. B. durch einen [[Gerichtsvollzieher]];  (iii) Überwachung der Zwangsvollstreckung: Das Vollstreckungsgericht überwacht den Ablauf der Zwangsvollstreckung und sorgt dafür, dass sie rechtmäßig erfolgt. Es stellt sicher, dass der Gläubiger Zugang zu den pfändbaren Vermögenswerten des Schuldners erhält"}, {"kategorie": "", "text": "Das Vollstreckungsgericht befasst sich auch mit Einwänden und Rechtsmitteln des Schuldners gegen Zwangsvollstreckungsmaßnahmen. Der Schuldner kann beim Vollstreckungsgericht z. B. [[Einspruch]] gegen die [[Pfändung]] einlegen, insbesondere wenn er die Pfändung für ungerechtfertigt hält"}, {"kategorie": "", "text": "In der Regel ist das [[Bezirksgericht]], in dessen Bezirk der Schuldner seinen Wohnsitz hat, als Vollstreckungsgericht zuständig. Bei der Zwangsvollstreckung auf Immobilien ist das Gericht zuständig, in dessen Bezirk das Grundstück liegt."}]'::jsonb, ''),
  ('pfaendungsvafoan', 'Pfändungsvafoan', '', '', '', '', 'Pfändungsverfahren', '[{"kategorie": "jur.", "text": "\"rechtliches Verfahren, bei dem ein [[Gläubiger]] eine [[Zwangsvollstreckung]] einleitet, um seine Forderungen gegen einen [[Schuldner]] durch die [[Pfändung]] von dessen Vermögenswerten zu sichern und zu befriedigen\""}, {"kategorie": "", "text": "Das Pfändungsverfahren dient dazu, Geldforderungen zwangsweise durchzusetzen, wenn der Schuldner seine Schulden nicht freiwillig begleicht"}, {"kategorie": "", "text": "Das Pfändungsverfahren ermöglicht es dem Gläubiger, auf Vermögenswerte des Schuldners, wie Lohn, Bankguthaben oder bewegliche Sachen, zuzugreifen"}, {"kategorie": "", "text": "Der Gläubiger muss einen [[vollstreckbaren]] Titel besitzen, wie ein [[Gerichtsurteil]], einen [[Vollstreckungsbescheid]] oder eine notariell beurkundete Verpflichtung, die die Forderung rechtlich feststellt. Ohne diesen Titel kann keine Pfändung erfolgen"}, {"kategorie": "", "text": "Der Gläubiger stellt beim zuständigen [[Vollstreckungsgericht]] oder direkt beim [[Gerichtsvollzieher]] einen [[Pfändungsantrag]]. Dieser Antrag muss genaue Angaben zur Forderung und zu den Vermögenswerten des Schuldners enthalten, die gepfändet werden sollen (z. B. Lohn, Konto oder bewegliche Sachen)"}, {"kategorie": "", "text": "Das Gericht prüft den Antrag und erlässt, wenn alle Voraussetzungen erfüllt sind, einen Pfändungs- und Überweisungsbeschluss. Dieser [[Beschluss]] erlaubt es dem Gläubiger, bestimmte Vermögenswerte des Schuldners zu pfänden und an sich überweisen zu lassen"}, {"kategorie": "", "text": "Arten der Pfändung: (i) [[Lohnpfändung]]: Der Arbeitgeber des Schuldners wird angewiesen, einen Teil des Lohns direkt an den Gläubiger abzuführen;  (ii) [[Kontopfändung]]: Die Bank des Schuldners wird angewiesen, Guthaben auf dem Konto des Schuldners zu sperren und es zur Tilgung der Schuld zu verwenden;  (iii) [[Sachpfändung]]: Der Gerichtsvollzieher beschlagnahmt bewegliche Sachen des Schuldners (z. B. Fahrzeuge, Wertsachen), die dann versteigert werden, um die Schulden zu begleichen"}, {"kategorie": "", "text": "In bestimmten Fällen, wie bei der Lohn- und Kontopfändung, gelten gesetzlich festgelegte Pfändungsfreigrenzen, die sicherstellen, dass dem Schuldner ein bestimmtes [[Existenzminimum]] für den Lebensunterhalt verbleibt"}, {"kategorie": "", "text": "Gepfändete Sachen werden in der Regel öffentlich versteigert, und der Erlös wird zur Begleichung der Forderung des Gläubigers verwendet. Bei Geldforderungen wie Lohn- oder Kontopfändungen wird der gepfändete Betrag direkt an den Gläubiger überwiesen."}]'::jsonb, ''),
  ('pfaendungsfreibetroog', 'Pfändungsfreibetroog', '', '', '', '', 'Pfändungsfreibetrag', '[{"kategorie": "jur.", "text": "\"gesetzlich festgelegter Betrag, der bei einem [[Schuldner]] im Rahmen einer [[Lohn-]] oder [[Kontopfändung]] nicht gepfändet werden darf, um solcherart den notwendigen Lebensunterhalt des Schuldners und den seiner unterhaltsberechtigten Personen zu sichern\""}, {"kategorie": "", "text": "Dieser Betrag darf vom Gläubiger nicht gepfändet werden, selbst wenn eine [[Zwangsvollstreckung]] vorliegt. Der Pfändungsfreibetrag soll sicherstellen, dass der Schuldner auch nach der Pfändung weiterhin seine grundlegenden Bedürfnisse, wie Wohnen, Ernährung und medizinische Versorgung, decken kann"}, {"kategorie": "", "text": "Der Pfändungsfreibetrag schützt das [[Existenzminimum]] des Schuldners, also den Betrag, der ihm für die Bestreitung seines Lebensunterhalts verbleiben muss. Dieser Betrag richtet sich nach dem Einkommen des Schuldners und der Anzahl der Personen, für die er unterhaltspflichtig ist (z. B. Kinder oder Ehepartner)"}, {"kategorie": "", "text": "Bei einer [[Lohnpfändung]] bleibt der Betrag, der unter dem Pfändungsfreibetrag liegt, unangetastet. Der darüber hinausgehende Teil des Einkommens kann zur Begleichung der Forderungen des Gläubigers verwendet werden"}, {"kategorie": "", "text": "Bei einer [[Kontopfändung]] ist der Pfändungsfreibetrag ebenfalls relevant. Der Schuldner kann den unpfändbaren Betrag weiterhin vom Konto abheben, um seinen Lebensunterhalt zu bestreiten. In vielen Fällen muss das Konto in ein Pfändungsschutzkonto (P-Konto) umgewandelt werden, um den Pfändungsfreibetrag zu schützen"}, {"kategorie": "", "text": "Der Pfändungsfreibetrag wird regelmäßig an die wirtschaftlichen Verhältnisse und Lebenshaltungskosten angepasst. Er variiert je nach Höhe des Einkommens und der Anzahl der Unterhaltsverpflichtungen des Schuldners"}, {"kategorie": "", "text": "Bestimmte Einkünfte, wie z. B. Sozialleistungen ([[Arbeitslosengeld]], Kindergeld) oder Renten, sind entweder ganz oder teilweise unpfändbar und unterliegen speziellen Schutzvorschriften."}]'::jsonb, ''),
  ('pfaendungsbeschluss', 'Pfändungsbeschluss', '', '', '', '', 'Pfändungsbeschluss', '[{"kategorie": "", "text": "Mit diesem [[Beschluss]] wird ein bestimmter Vermögensgegenstand des Schuldners, in der Regel Lohn, Gehalt oder Bankguthaben, gepfändet und die Zahlung dieses Betrags an den Gläubiger angeordnet"}, {"kategorie": "", "text": "Der Pfändungs- und Überweisungsbeschluss setzt einen [[vollstreckbaren]] Titel voraus, wie ein [[Gerichtsurteil]], ein [[Vollstreckungsbescheid]] oder eine notarielle Urkunde, die die Forderung des Gläubigers gegen den Schuldner rechtskräftig feststellt"}, {"kategorie": "", "text": "Der Pfändungsbeschluss bewirkt, dass der entsprechende Vermögenswert des Schuldners, wie Lohn, Gehalt oder ein Kontoguthaben, rechtlich gesperrt wird. Der Schuldner kann ab diesem Zeitpunkt nicht mehr über diesen Teil seines Vermögens verfügen"}, {"kategorie": "", "text": "Der gepfändete Betrag wird vom Arbeitgeber (bei [[Lohnpfändung]]) oder von der Bank (bei [[Kontopfändung]]) direkt an den Gläubiger überwiesen, um die offene Forderung zu begleichen"}, {"kategorie": "", "text": "Besonders bei der Lohn- oder Kontopfändung gibt es gesetzlich festgelegte [[Pfändungsfreigrenzen]], die sicherstellen, dass dem Schuldner ein bestimmtes [[Existenzminimum]] für seinen Lebensunterhalt verbleibt"}, {"kategorie": "", "text": "Sobald der Beschluss vom Gericht erlassen und dem [[Drittschuldner]] (z. B. dem Arbeitgeber oder der Bank) zugestellt wurde, sind diese verpflichtet, die entsprechenden Beträge an den Gläubiger abzuführen. Der Schuldner wird darüber ebenfalls informiert"}, {"kategorie": "", "text": "Der Schuldner hat die Möglichkeit, gegen den Pfändungs- und Überweisungsbeschluss innerhalb einer bestimmten Frist [[Einspruch]] einzulegen, z. B. wenn er der Meinung ist, dass die Forderung nicht rechtmäßig ist oder die Pfändungsfreigrenze nicht beachtet wurde."}]'::jsonb, ''),
  ('einschbruch', 'Einschbruch', '', '', '', '', 'Einspruch', '[{"kategorie": "jur.", "text": "\"rechtliches Mittel in Österreich, mit dem eine Person gegen eine gerichtliche Entscheidung oder einen [[Bescheid]] vorgeht\""}, {"kategorie": "", "text": "Der Einspruch ermöglicht es dem Betroffenen, die Überprüfung einer Entscheidung zu verlangen, wenn er diese für falsch hält"}, {"kategorie": "", "text": "Der Einspruch ist insbesondere im Zusammenhang mit [[Mahnverfahren]] und [[Vollstreckungsverfahren]] relevant, kann aber auch in anderen Verfahrensarten Anwendung finden"}, {"kategorie": "", "text": "Im Mahnverfahren kann der Schuldner Einspruch gegen einen Mahn- oder [[Vollstreckungsbescheid]] erheben, wenn er die Forderung des Gläubigers für unberechtigt hält oder andere Einwände vorbringen möchte. Der Einspruch verhindert, dass der Bescheid rechtskräftig wird und führt zur Prüfung der Angelegenheit im Rahmen eines ordentlichen Verfahrens"}, {"kategorie": "", "text": "Der Einspruch muss innerhalb einer bestimmten Frist – in der Regel innerhalb von 14 Tagen nach Zustellung des Bescheids – schriftlich beim zuständigen Gericht oder der Behörde eingereicht werden. Versäumt der Betroffene diese Frist, wird die Entscheidung oder der Bescheid rechtskräftig und vollstreckbar"}, {"kategorie": "", "text": "Ein fristgerechter Einspruch hemmt in der Regel die Vollstreckung der angegriffenen Entscheidung. Das bedeutet, dass keine Zwangsvollstreckungsmaßnahmen erfolgen können, solange der Einspruch nicht geprüft und entschieden wurde"}, {"kategorie": "", "text": "Nach dem Einspruch wird das Verfahren in die nächste Stufe überführt, beispielsweise in ein ordentlichesà Gerichtsverfahren, in dem die Anspruchsgrundlagen geprüft werden. Falls der Einspruch zurückgewiesen wird, wird der ursprüngliche Bescheid rechtskräftig"}, {"kategorie": "", "text": "Unterschied zum [[Rekurs]] oder zur [[Berufung]]: Der Einspruch bezieht sich in der Regel auf [[Bescheide]] oder Entscheidungen in vereinfachten Verfahren (wie dem [[Mahnverfahren]]). Im Gegensatz dazu richtet sich ein [[Rekurs]] oder eine [[Berufung]] gegen Entscheidungen in ordentlichen Gerichtsverfahren."}]'::jsonb, ''),
  ('voischdreckungsbescheid', 'Voischdreckungsbescheid', '', '', '', '', 'Vollstreckungsbescheid', '[{"kategorie": "jur.", "text": "\"gerichtliches Dokument, das es einem [[Gläubiger]] ermöglicht, eine [[Zwangsvollstreckung]] gegen einen [[Schuldner]] durchzuführen, um eine offene Geldforderung einzutreiben\""}, {"kategorie": "", "text": "Der Vollstreckunsbescheid wird im Rahmen eines [[Mahnverfahrens]] erlassen, wenn der Schuldner auf einen [[Mahnbescheid]] nicht reagiert oder keine Einwände erhebt"}, {"kategorie": "", "text": "Der Vollstreckungsbescheid hat die gleiche Wirkung wie ein gerichtliches [[Urteil]] und stellt einen [[vollstreckbaren]] Titel dar, auf dessen Grundlage der Gläubiger Maßnahmen zur [[Pfändung]] oder [[Zwangsvollstreckung]] einleiten kann"}, {"kategorie": "", "text": "Der Schuldner hat die Möglichkeit, innerhalb einer Frist von zwei Wochen nach Zustellung des Vollstreckungsbescheids Einspruch einzulegen. Wird Einspruch erhoben, wird der Fall in ein reguläres Gerichtsverfahren überführt, in dem der Anspruch geprüft wird."}]'::jsonb, ''),
  ('auktionatoa', 'Auktionatoa', '', '', '', '', 'Auktionatoa', '[{"kategorie": "jur.", "text": "\"Person, die eine [[Auktion]] leitet und für den ordnungsgemäßen Ablauf des Bietverfahrens verantwortlich ist\""}, {"kategorie": "", "text": "Der Auktionator nimmt die Gebote der Teilnehmer entgegen und vergibt den Zuschlag an den Höchstbietenden, wodurch der Verkauf des angebotenen Gegenstands rechtsverbindlich wird"}, {"kategorie": "", "text": "Der Auktionator kann verschiedene Arten von Auktionen leiten, wie etwa [[englische]] Auktionen (Gebote steigen) oder [[holländische]] Auktionen (Gebote sinken), sowohl in klassischen, physischen Auktionshäusern als auch bei Online-Auktionen"}, {"kategorie": "", "text": "Der Auktionator ist damit die zentrale Figur in einer Auktion, die für den ordnungsgemäßen und rechtlich einwandfreien Ablauf des Verfahrens sorgt und sicherstellt, dass der Verkauf transparent und effizient durchgeführt wird."}]'::jsonb, ''),
  ('auktion', 'Auktion', '', '', '', '', 'Auktion', '[{"kategorie": "jur.", "text": "\"Verfahren, bei dem Waren oder Dienstleistungen öffentlich angeboten und an denjenigen verkauft werden, der das höchste Gebot abgibt\""}, {"kategorie": "", "text": "Es handelt sich dabei um eine spezielle Art des Verkaufs, bei dem der Preis nicht fest vorgegeben ist, sondern durch das Bieten von Interessenten (den Bietern) ermittelt wird"}, {"kategorie": "", "text": "Auktionen können für eine Vielzahl von Gegenständen durchgeführt werden, darunter Kunstwerke, Immobilien, Fahrzeuge, Sammlerstücke und vieles mehr"}, {"kategorie": "", "text": "Die Auktion wird von einem [[Auktionator]] geleitet, der die Gebote entgegennimmt und den Ablauf der Auktion organisiert. Der Auktionator vergibt den Zuschlag an den Höchstbietenden"}, {"kategorie": "", "text": "Die Teilnehmer der Auktion geben nacheinander Gebote ab. Dies kann in steigender Reihenfolge erfolgen, bis kein höheres Gebot mehr abgegeben wird. Es gibt auch andere Auktionsformen, bei denen das Bieten auf unterschiedliche Weise abläuft (z. B. verdeckte Gebote)"}, {"kategorie": "", "text": "Das Ziel der Auktion ist es, den höchsten Preis zu ermitteln. Der Bieter mit dem höchsten Gebot erhält den Zuschlag, wodurch der Kaufvertrag zustande kommt und der Bieter verpflichtet ist, den gebotenen Preis zu zahlen"}, {"kategorie": "", "text": "Der Zuschlag erfolgt, wenn kein höheres Gebot mehr abgegeben wird. Ab diesem Zeitpunkt ist der Höchstbietende der neue Eigentümer der angebotenen Ware oder Dienstleistung, vorausgesetzt, er zahlt den vereinbarten Preis"}, {"kategorie": "", "text": "Auktionsarten:  (i) [[Englische]] Auktion: Der Preis steigt mit jedem Gebot, bis der Höchstbietende den Zuschlag erhält;  (ii) [[Holländische]] Auktion: Der Preis sinkt schrittweise, bis ein Bieter bereit ist, den aktuellen Preis zu akzeptieren;  (iii) [[Verdeckte]] Auktion: Die Gebote werden verdeckt abgegeben, und der Höchstbietende wird nach Ablauf der Frist ermittelt;  (iv) Online-Auktion: Eine moderne Form der Auktion, bei der das Bieten über das Internet erfolgt"}, {"kategorie": "", "text": "Auktionen werden in verschiedenen Bereichen verwendet, wie z. B. in der Kunst- und Antiquitätenbranche, im Immobiliensektor, bei Insolvenzen, aber auch bei Online-Plattformen wie eBay."}]'::jsonb, ''),
  ('vaschdeigarung', 'Vaschdeigarung', '', '', '', '', 'Versteigerung', '[{"kategorie": "jur.", "text": "\"Verfahren, bei dem Vermögensgegenstände öffentlich angeboten und an den Meistbietenden verkauft werden\""}, {"kategorie": "", "text": "Die Versteigerung dient oft dazu, den bestmöglichen Preis für eine Sache zu erzielen"}, {"kategorie": "", "text": "Versteigerungen werden in verschiedenen Kontexten durchgeführt, unter anderem zur [[Verwertung]] gepfändeter Sachen im Rahmen einer [[Zwangsvollstreckung]], beim Verkauf von Immobilien oder bei [[Auktionen]] von Kunstwerken und anderen Wertgegenständen"}, {"kategorie": "", "text": "Die Versteigerung wird von einem [[Auktionator]] (bei Zwangsversteigerungen oft ein [[Gerichtsvollzieher]]) geleitet, der die Gebote entgegennimmt und den Zuschlag an den Höchstbietenden erteilt"}, {"kategorie": "", "text": "Die Teilnehmer der Versteigerung (Bieter) geben nacheinander Gebote ab. Der Bieter mit dem höchsten Gebot erhält den Zuschlag und erwirbt den Gegenstand. Es gibt verschiedene Arten von Versteigerungen, darunter öffentliche und private Auktionen"}, {"kategorie": "", "text": "In rechtlichen Verfahren, wie z. B. bei einer [[Sachpfändung]] oder [[Zwangsvollstreckung]], wird eine Versteigerung durchgeführt, um die Vermögensgegenstände des Schuldners zu verwerten und die Forderungen des Gläubigers zu befriedigen. Die dabei erzielten Einnahmen werden zur Schuldentilgung verwendet"}, {"kategorie": "", "text": "Gegenstände, die versteigert werden können, reichen von beweglichen Sachen (wie Möbel, Kunstwerke, Fahrzeuge) bis hin zu Immobilien. Bei Zwangsversteigerungen können auch Grundstücke und Häuser verkauft werden"}, {"kategorie": "", "text": "Der Zuschlag wird demjenigen Bieter erteilt, der das höchste Gebot abgibt. Ab diesem Zeitpunkt geht das Eigentum des versteigerten Gegenstands auf den Käufer über, und der Kaufpreis wird fällig"}, {"kategorie": "", "text": "Das Ziel einer Versteigerung ist es, den bestmöglichen Preis für den zu verkaufenden Gegenstand zu erzielen. Bei Zwangsversteigerungen dient sie zusätzlich der Befriedigung der Gläubiger."}]'::jsonb, ''),
  ('sachpfaendnung', 'Sachpfändnung', '', '', '', '', 'Sachpfändung', '[{"kategorie": "jur.", "text": "\"Maßnahme der [[Zwangsvollstreckung]], bei der bewegliche Sachen des [[Schuldners]] durch einen [[Gerichtsvollzieher]] beschlagnahmt werden, um eine offene Forderung des Gläubigers zu befriedigen\""}, {"kategorie": "", "text": "Ziel der Sachpfändung ist es, Vermögensgegenstände des Schuldners zu verwerten (meist durch [[Versteigerung]]), um den Erlös zur Begleichung der Schuld zu verwenden"}, {"kategorie": "", "text": "Die Sachpfändung erfolgt auf Grundlage eines gerichtlichen [[Vollstreckungstitels]], wie etwa eines [[Urteils]] oder eines [[Vollstreckungsbescheids]]. Der Gläubiger muss beim Gerichtsvollzieher die Zwangsvollstreckung beantragen"}, {"kategorie": "", "text": "Der Gerichtsvollzieher besucht den Schuldner vor Ort (z. B. in dessen Wohnung oder Geschäftsräumen) und prüft, welche beweglichen Gegenstände pfändbar sind. Diese Gegenstände werden anschließend beschlagnahmt"}, {"kategorie": "", "text": "Gepfändet werden können in der Regel wertvolle Gegenstände wie Fahrzeuge, Schmuck, Elektronik, Möbel oder sonstige bewegliche Vermögenswerte, die dem Schuldner gehören. Bestimmte Sachen sind jedoch unpfändbar, insbesondere Gegenstände, die für den täglichen Lebensbedarf oder die Ausübung des Berufs notwendig sind (z. B. Kleidung, Werkzeuge)"}, {"kategorie": "", "text": "Bestimmte Gegenstände sind durch gesetzliche Regelungen vor der Pfändung geschützt, wie etwa notwendiger Hausrat (z. B. Betten, Küchenutensilien), Kleidung, Arbeitsmittel oder Dinge, die zur Deckung des Existenzminimums notwendig sind"}, {"kategorie": "", "text": "Nach der Pfändung organisiert der Gerichtsvollzieher die Verwertung der gepfändeten Sachen, meist durch eine öffentliche [[Versteigerung]]. Der Erlös wird dann zur Begleichung der offenen Forderung des Gläubigers verwendet"}, {"kategorie": "", "text": "Der aus der Verwertung der gepfändeten Sachen erzielte Erlös wird zur Tilgung der Schulden verwendet. Reicht der Erlös nicht aus, bleibt der Schuldner für den Restbetrag weiterhin verpflichtet. Falls der Erlös höher ist als die Forderung, wird der überschüssige Betrag an den Schuldner zurückerstattet."}]'::jsonb, ''),
  ('kontopfaendung', 'Kontopfändung', '', '', '', '', 'Kontopfändung', '[{"kategorie": "jur.", "text": "\"Maßnahme der [[Zwangsvollstreckung]], bei der das Bankguthaben eines [[Schuldners]] gepfändet wird, um offene Forderungen eines [[Gläubigers]] zu befriedigen\""}, {"kategorie": "", "text": "Durch die Kontopfändung wird der Zugriff auf das Konto des Schuldners eingeschränkt, und das gepfändete Guthaben wird zur Tilgung der Schulden an den Gläubiger überwiesen"}, {"kategorie": "", "text": "Die Kontopfändung setzt einen gerichtlichen [[Beschluss]] voraus, den der Gläubiger beim zuständigen Gericht beantragt. Das Gericht erlässt daraufhin einen Pfändungs- und Überweisungsbeschluss, der die Bank des Schuldners anweist, das Guthaben zu sperren und die Forderung des Gläubigers zu begleichen"}, {"kategorie": "", "text": "Nach Zustellung des [[Pfändungsbeschlusses]] an die Bank wird das Konto des Schuldners gesperrt. Das bedeutet, dass der Schuldner nur noch eingeschränkt oder gar nicht mehr über das vorhandene Guthaben verfügen kann"}, {"kategorie": "", "text": "Bei einer Kontopfändung bleibt dem Schuldner ein gesetzlich festgelegter Betrag, der sogenannte [[Pfändungsfreibetrag]], erhalten, um seinen Lebensunterhalt zu sichern. Dieser Betrag richtet sich nach der Höhe des Einkommens und der Anzahl der unterhaltsberechtigten Personen"}, {"kategorie": "", "text": "Gepfändet werden kann nur das Guthaben, das sich tatsächlich auf dem Konto befindet. Es dürfen keine negativen Kontostände oder Kreditlinien gepfändet werden"}, {"kategorie": "", "text": "Das gepfändete Guthaben wird, nachdem die Sperre wirksam geworden ist, direkt von der Bank an den Gläubiger überwiesen, bis die Forderung vollständig beglichen ist oder keine weiteren pfändbaren Beträge mehr vorhanden sind"}, {"kategorie": "", "text": "Bestimmte Einkünfte, wie etwa Sozialleistungen oder Kindergeld, sind gesetzlich vor der [[Pfändung]] geschützt. Diese Beträge dürfen nicht gepfändet werden, auch wenn sie auf dem Konto des Schuldners eingehen."}]'::jsonb, ''),
  ('pfaendung', 'Pfändung', '', '', '', '', 'Pfändung', '[{"kategorie": "jur.", "text": "\"Maßnahme der [[Zwangsvollstreckung]], bei der Vermögenswerte eines [[Schuldners]] beschlagnahmt werden, um offene Forderungen eines [[Gläubigers]] zu befriedigen\""}, {"kategorie": "", "text": "Sie dient dazu, den Gläubiger zu schützen, indem sichergestellt wird, dass der Schuldner seine Schulden auch dann begleicht, wenn er freiwillig nicht dazu bereit oder in der Lage ist"}, {"kategorie": "", "text": "Eine Pfändung erfolgt in der Regel nur nach einem gerichtlichen [[Beschluss]]. Der Gläubiger muss beim zuständigen Gericht einen [[Pfändungsantrag]] stellen und einen [[Vollstreckungstitel]], wie z. B. ein Urteil, einen Vollstreckungsbescheid oder eine notarielle Urkunde, vorweisen"}, {"kategorie": "", "text": "Gepfändet werden können verschiedene Vermögenswerte des Schuldners, z. B.:  (i) Lohn oder Gehalt (Lohnpfändung),  (ii) Kontoguthaben (Kontopfändung),  (iii) bewegliche Sachen (z. B. Fahrzeuge, Wertsachen),  (iv) [[unbewegliches]] Vermögen wie Immobilien ([[Zwangsversteigerung]])"}, {"kategorie": "", "text": "Die Pfändung wird in der Regel durch einen [[Gerichtsvollzieher]] durchgeführt. Dieser beschlagnahmt die pfändbaren Vermögenswerte und sorgt für deren Verwertung, wenn der Schuldner die offene Forderung nicht begleicht"}, {"kategorie": "", "text": "Insbesondere bei der Lohn- oder Kontopfändung gibt es gesetzlich festgelegte [[Pfändungsfreigrenzen]], die sicherstellen, dass dem Schuldner ein bestimmter Betrag für den Lebensunterhalt verbleibt. Diese Grenzen berücksichtigen auch die Anzahl der unterhaltsberechtigten Personen"}, {"kategorie": "", "text": "Nach der Pfändung werden die beschlagnahmten Vermögenswerte im Rahmen einer Verwertung (z. B. durch Versteigerung oder Verkauf) dazu genutzt, die Forderungen des Gläubigers zu befriedigen. Falls die Pfändung von Geldmitteln erfolgt, werden diese direkt an den Gläubiger überwiesen"}, {"kategorie": "", "text": "Der Schuldner hat bestimmte Rechte, wie etwa das Recht auf Einspruch gegen eine Pfändung oder auf Schutz bestimmter unpfändbarer Gegenstände (z. B. Haushaltsgegenstände oder Arbeitsmittel)."}]'::jsonb, ''),
  ('glaeubiga', 'Gläubiga', '', '', '', '', 'Gläubiger', '[{"kategorie": "jur.", "text": "\"natürliche oder juristische Person, die gegenüber einer anderen Person oder Firma/Organisation (dem [[Schuldner]]) einen rechtlich durchsetzbaren Anspruch auf eine Leistung hat\""}, {"kategorie": "", "text": "Diese Leistung kann aus der Zahlung von Geld, der Lieferung von Waren oder der Erbringung von Dienstleistungen bestehen"}, {"kategorie": "", "text": "Der Gläubiger hat das Recht, die Erfüllung dieser Verpflichtung einzufordern"}, {"kategorie": "", "text": "Der Gläubiger besitzt eine rechtlich anerkannte Forderung gegenüber dem Schuldner. Diese Forderung kann aus einem Vertrag (z. B. einem Darlehen), einem Schadensersatzanspruch oder einer gesetzlichen Verpflichtung entstehen"}, {"kategorie": "", "text": "Der Gläubiger hat das Recht, vom Schuldner eine bestimmte Leistung zu verlangen, die in der Regel in einer Zahlung, Lieferung oder Handlung besteht"}, {"kategorie": "", "text": "In bestimmten Fällen hat der Gläubiger Sicherungsrechte, wie z. B. eine [[Hypothek]] oder ein [[Pfandrecht]], um seine Forderung abzusichern. Diese Rechte erlauben es ihm, auf Vermögenswerte des Schuldners zuzugreifen, wenn dieser seine Verpflichtung nicht erfüllt"}, {"kategorie": "", "text": "Falls der Schuldner nicht freiwillig leistet, kann der Gläubiger seine Forderung gerichtlich geltend machen. Dies kann bis zur [[Zwangsvollstreckung]] führen, bei der Vermögenswerte des Schuldners gepfändet oder verkauft werden, um die Forderung zu befriedigen"}, {"kategorie": "", "text": "Es gibt verschiedene Arten von Gläubigern, wie z. B. private Gläubiger (z. B. eine Person, die einem Freund Geld geliehen hat), institutionelle Gläubiger (wie Banken oder Unternehmen) und staatliche Gläubiger (z. B. das Finanzamt)."}]'::jsonb, ''),
  ('grundbuach', 'Grundbuach', '', '', '', '', 'Grundbuch', '[{"kategorie": "jur.", "text": "\"öffentliches Register in Österreich, das alle rechtlichen Informationen über Grundstücke und deren Eigentümer enthält\""}, {"kategorie": "", "text": "Es wird von den [[Bezirksgerichten]] geführt und dient der rechtlichen Sicherung von Eigentums- und anderen dinglichen Rechten an Grundstücken und Immobilien"}, {"kategorie": "", "text": "Das Grundbuch schafft Transparenz und Rechtssicherheit im Immobilienverkehr, da aus ihm hervorgeht, wem ein Grundstück gehört und welche Belastungen darauf liegen"}, {"kategorie": "", "text": "Abschnitte des Grundbuchs:  (i) A-Blatt (Gutbestandsblatt): Hier werden die grundlegenden Informationen zum Grundstück festgehalten, wie Lage, Größe und Art der Liegenschaft;  (ii) B-Blatt (Eigentumsblatt): Hier sind der Eigentümer und seine Rechte eingetragen;  (iii) C-Blatt (Lastenblatt): Hier sind alle Belastungen des Grundstücks eingetragen, wie Pfandrechte, Hypotheken oder Dienstbarkeiten"}, {"kategorie": "", "text": "Das Grundbuch ist öffentlich einsehbar. Jeder kann gegen eine Gebühr Einsicht nehmen, um Informationen über die Eigentumsverhältnisse und Belastungen eines Grundstücks zu erhalten"}, {"kategorie": "", "text": "Die Eintragung ins Grundbuch hat rechtliche Wirkung. Ein Grundstücksverkauf wird erst mit der Eintragung des neuen Eigentümers ins Grundbuch wirksam. Auch [[Hypotheken]] oder andere Belastungen müssen eingetragen werden, um gültig zu sein."}]'::jsonb, ''),
  ('nochloss', 'Nochloss', '', '', '', '', 'Nachlass', '[{"kategorie": "jur.", "text": "\"das gesamte Vermögen und die Verbindlichkeiten (Schulden), die eine Person im Zeitpunkt ihres Todes hinterlässt\""}, {"kategorie": "", "text": "Der Nachlass umfasst alle beweglichen und unbeweglichen Vermögensgegenstände, Forderungen, Rechte, sowie Schulden und Verpflichtungen, die auf die Erben oder andere berechtigte Personen übergehen"}, {"kategorie": "", "text": "Wichtige Bestandteile eines Nachlasses können sein:  (i) Vermögenswerte: Dazu gehören beispielsweise Immobilien, Bankguthaben, Wertpapiere, Fahrzeuge, persönliche Gegenstände und andere Eigentumsrechte, die der Verstorbene besaß;  (ii) Forderungen und Rechte: Der Verstorbene kann Ansprüche gegenüber Dritten hinterlassen, wie ausstehende Zahlungen oder Rechte aus Verträgen;  (iii) Verbindlichkeiten (Schulden): Ebenso umfasst der Nachlass auch die Schulden und Verpflichtungen des Verstorbenen, die auf die Erben übergehen, etwa Kredite, offene Rechnungen oder sonstige finanzielle Verpflichtungen;  (iv) Verträge und laufende Rechtsverhältnisse: Verträge, die der Verstorbene abgeschlossen hat, gehen in der Regel auf die Erben über, es sei denn, sie erlöschen mit dem Tod der Person (wie etwa persönliche Dienstverträge)"}, {"kategorie": "", "text": "Der Nachlass wird in einem Verlassenschaftsverfahren geregelt, das in Österreich von einem [[Notar]] als Gerichtskommissär geleitet wird. Ziel dieses Verfahrens ist es, den Nachlass festzustellen, die Erben zu bestimmen und eine rechtmäßige Verteilung des Nachlasses gemäß den Bestimmungen des Erbrechts und einem eventuellen Testament vorzunehmen"}, {"kategorie": "", "text": "Erben haben die Möglichkeit, den Nachlass anzunehmen, bedingt anzunehmen (das bedeutet, sie haften nur bis zur Höhe des Nachlasswertes) oder auszuschlagen, insbesondere wenn der Nachlass überschuldet ist"}]'::jsonb, ''),
  ('neemintaveniint', 'Neemintaveniint', '', '', '', '', 'Nebenintervenient', '[{"kategorie": "jur.", "text": "\"natürliche oder juristische Person, die sich in einem bereits laufenden [[Gerichtsverfahren]] auf der Seite einer der [[Prozessparteien]] beteiligt, um deren Interessen zu unterstützen\""}, {"kategorie": "", "text": "Der Nebenintervenient tritt freiwillig dem Verfahren bei, weil er ein rechtliches Interesse am Ausgang des Verfahrens hat, obwohl er nicht die Hauptpartei im Prozess ist"}, {"kategorie": "", "text": "Der Nebenintervenient hat ein eigenes rechtliches Interesse am Ausgang des Verfahrens, da die Entscheidung des Gerichts seine eigenen Rechte oder Pflichten mittelbar beeinflussen kann"}, {"kategorie": "", "text": "Der Nebenintervenient schließt sich einer der beiden Prozessparteien ([[Kläger]] oder [[Beklagter]]) an und unterstützt deren Position durch eigene Erklärungen, Stellungnahmen oder Beweismittel"}, {"kategorie": "", "text": "Der Nebenintervenient hat bestimmte Verfahrensrechte, wie das [[Recht]] auf Akteneinsicht, das Stellen von [[Beweisanträgen]] und das Vorbringen von Argumenten. Er kann jedoch nicht eigenständig über den Gegenstand des Rechtsstreits verfügen oder das Verfahren beeinflussen, sondern agiert immer im Rahmen der Hauptpartei, die er unterstützt"}, {"kategorie": "", "text": "Der Nebenintervenient bleibt formal gesehen Dritter im Verfahren und ist nicht direkt an die rechtlichen Verpflichtungen des [[Urteils]] gebunden. Seine Rolle ist rein unterstützend, und er kann nicht eigenständig [[Rechtsmittel]] gegen das Urteil einlegen, außer sein eigenes rechtliches Interesse wird direkt beeinträchtigt"}, {"kategorie": "", "text": "In Österreich ist die Nebenintervention in der [[Zivilprozessordnung]] (ZPO) geregelt. Ein typisches Beispiel für eine Nebenintervention ist ein Versicherungsunternehmen, das sich einem Verfahren anschließt, um die Position seines Versicherungsnehmers zu unterstützen."}]'::jsonb, ''),
  ('prozessbeteiligta', 'Prozessbeteiligta', '', '', '', '', 'Prozessbeteiligter', '[{"kategorie": "jur.", "text": "\"natürliche oder juristische Person oder Institution, die an einem gerichtlichen Verfahren teilnimmt, ohne notwendigerweise eine [[Prozesspartei]] im engeren Sinne zu sein\""}, {"kategorie": "", "text": "Prozessbeteiligte können neben den eigentlichen Parteien auch andere Personen oder Institutionen sein, deren Rechte oder Interessen durch das Verfahren betroffen sind oder die aufgrund einer gesetzlichen Regelung am Verfahren teilnehmen"}, {"kategorie": "", "text": "Während Prozessparteien (z. B. Kläger und Beklagte) direkt über ihre Rechte und Pflichten streiten, können Prozessbeteiligte eine weniger zentrale Rolle spielen, jedoch dennoch am Verfahren teilnehmen und es beeinflussen"}, {"kategorie": "", "text": "Beispiele für Prozessbeteiligte:  (i) Zeugen: Personen, die im Rahmen des Prozesses Aussagen machen und zur Klärung des Sachverhalts beitragen sollen;  (ii) Sachverständige: Experten, die vom Gericht beauftragt werden, ihre Fachkenntnisse einzubringen, z. B. durch Gutachten;  (iii) Dritte mit rechtlichem Interesse: Personen oder Organisationen, deren rechtliche Interessen mittelbar betroffen sind, wie etwa Erben in einem [[Nachlassverfahren]] oder Mieter bei Streitigkeiten zwischen Vermietern und Käufern einer Immobilie;  (iv) Staatsanwaltschaft: In [[Strafverfahren]] übernimmt die [[Staatsanwaltschaft]] als Prozessbeteiligte die Aufgabe der [[Strafverfolgung]] und tritt als Ankläger auf;  (v) In [[Verwaltungsverfahren]] können z. B. auch Behörden oder andere öffentliche Institutionen Prozessbeteiligte sein, etwa wenn sie an der Entscheidung mitwirken oder von deren Ausgang betroffen sind"}, {"kategorie": "", "text": "Prozessbeteiligte haben bestimmte Rechte und Pflichten, die je nach ihrer Rolle im Verfahren variieren, etwa das Recht auf Anhörung oder die Pflicht, wahrheitsgemäße Aussagen zu machen."}]'::jsonb, ''),
  ('beteiligta', 'Beteiligta', '', '', '', '', 'Beteiligter', '[{"kategorie": "", "text": "Prozessbeteiligte können neben den eigentlichen Parteien auch andere Personen oder Institutionen sein, deren Rechte oder Interessen durch das Verfahren betroffen sind oder die aufgrund einer gesetzlichen Regelung am Verfahren teilnehmen"}, {"kategorie": "", "text": "Während Prozessparteien (z. B. Kläger und Beklagte) direkt über ihre Rechte und Pflichten streiten, können Prozessbeteiligte eine weniger zentrale Rolle spielen, jedoch dennoch am Verfahren teilnehmen und es beeinflussen"}, {"kategorie": "", "text": "Beispiele für Prozessbeteiligte:  (i) Zeugen: Personen, die im Rahmen des Prozesses Aussagen machen und zur Klärung des Sachverhalts beitragen sollen;  (ii) Sachverständige: Experten, die vom Gericht beauftragt werden, ihre Fachkenntnisse einzubringen, z. B. durch Gutachten;  (iii) Dritte mit rechtlichem Interesse: Personen oder Organisationen, deren rechtliche Interessen mittelbar betroffen sind, wie etwa Erben in einem [[Nachlassverfahren]] oder Mieter bei Streitigkeiten zwischen Vermietern und Käufern einer Immobilie;  (iv) Staatsanwaltschaft: In [[Strafverfahren]] übernimmt die [[Staatsanwaltschaft]] als Prozessbeteiligte die Aufgabe der [[Strafverfolgung]] und tritt als Ankläger auf;  (v) In [[Verwaltungsverfahren]] können z. B. auch Behörden oder andere öffentliche Institutionen Prozessbeteiligte sein, etwa wenn sie an der Entscheidung mitwirken oder von deren Ausgang betroffen sind"}, {"kategorie": "", "text": "Prozessbeteiligte haben bestimmte Rechte und Pflichten, die je nach ihrer Rolle im Verfahren variieren, etwa das Recht auf Anhörung oder die Pflicht, wahrheitsgemäße Aussagen zu machen."}]'::jsonb, ''),
  ('prozesspartei', 'Prozesspartei', '', '', '', '', 'Prozesspartei', '[{"kategorie": "jur.", "text": "\"natürliche oder juristische Person, die an einem gerichtlichen Verfahren beteiligt ist und deren Rechte oder Pflichten durch das Verfahren unmittelbar betroffen sind\""}, {"kategorie": "", "text": "Prozessparteien können entweder [[Kläger]] (oder Antragsteller) oder [[Beklagter]] (oder Antragsgegner) in Zivilverfahren, [[Angeklagte]] in Strafverfahren oder [[Beteiligte]] in anderen Verfahrensarten sein"}, {"kategorie": "", "text": "Die Prozesspartei hat verschiedene Rechte und Pflichten im Verfahren, darunter: (i) Recht auf [[rechtliches]] Gehör: Die Parteien haben das Recht, ihre Standpunkte und Argumente vor Gericht darzulegen und Beweise einzubringen;  (ii) Antrags- und Beweiserhebungsrecht: Die Prozessparteien können Anträge stellen, wie z. B. [[Beweisanträge]], und bestimmte Verfahrenshandlungen vornehmen, um ihre Position zu stützen;  (iii) Pflicht zur Mitwirkung: Parteien haben die Pflicht, im Verfahren mitzuwirken, z. B. durch die Beibringung von Beweisen oder die Teilnahme an Verhandlungen;  (iv) Rechtsmittelrecht: Prozessparteien können gegen gerichtliche Entscheidungen [[Rechtsmittel]] einlegen, etwa [[Berufung]] oder [[Revision]], um die Überprüfung des Urteils zu erreichen"}, {"kategorie": "", "text": "Im Zivilprozessrecht stehen sich in der Regel der [[Kläger]] (die Person, die das Verfahren einleitet) und der [[Beklagte]] (die Person, gegen die der Anspruch gerichtet ist) gegenüber"}, {"kategorie": "", "text": "Im Strafprozess sind die Hauptparteien der [[Angeklagte]] und die [[Staatsanwaltschaft]], die im Namen des [[Staates]] die [[Strafverfolgung]] betreibt."}]'::jsonb, ''),
  ('partei', 'Partei', '', '', '', '', 'Partei', '[{"kategorie": "jur.", "text": "\"natürliche oder juristische Person, die an einem gerichtlichen Verfahren beteiligt ist und deren Rechte oder Pflichten durch das Verfahren unmittelbar betroffen sind\""}, {"kategorie": "", "text": "Prozessparteien können entweder [[Kläger]] (oder Antragsteller) oder [[Beklagter]] (oder Antragsgegner) in Zivilverfahren, [[Angeklagte]] in Strafverfahren oder [[Beteiligte]] in anderen Verfahrensarten sein"}, {"kategorie": "", "text": "Die Prozesspartei hat verschiedene Rechte und Pflichten im Verfahren, darunter: (i) Recht auf [[rechtliches]] Gehör: Die Parteien haben das Recht, ihre Standpunkte und Argumente vor Gericht darzulegen und Beweise einzubringen;  (ii) Antrags- und Beweiserhebungsrecht: Die Prozessparteien können Anträge stellen, wie z. B. [[Beweisanträge]], und bestimmte Verfahrenshandlungen vornehmen, um ihre Position zu stützen;  (iii) Pflicht zur Mitwirkung: Parteien haben die Pflicht, im Verfahren mitzuwirken, z. B. durch die Beibringung von Beweisen oder die Teilnahme an Verhandlungen;  (iv) Rechtsmittelrecht: Prozessparteien können gegen gerichtliche Entscheidungen [[Rechtsmittel]] einlegen, etwa [[Berufung]] oder [[Revision]], um die Überprüfung des Urteils zu erreichen"}, {"kategorie": "", "text": "Im Zivilprozessrecht stehen sich in der Regel der [[Kläger]] (die Person, die das Verfahren einleitet) und der [[Beklagte]] (die Person, gegen die der Anspruch gerichtet ist) gegenüber"}, {"kategorie": "", "text": "Im Strafprozess sind die Hauptparteien der [[Angeklagte]] und die [[Staatsanwaltschaft]], die im Namen des [[Staates]] die [[Strafverfolgung]] betreibt."}]'::jsonb, ''),
  ('beweiswueadigung', 'Beweiswüadigung', '', '', '', '', 'Beweiswürdigung', '[{"kategorie": "jur.", "text": "\"Prozess, in dem das [[Gericht]] die im [[Verfahren]] erhobenen [[Beweise]] prüft und bewertet, um zu entscheiden, welche Tatsachen als erwiesen gelten\""}, {"kategorie": "", "text": "Dabei beurteilt das Gericht die Glaubwürdigkeit und Zuverlässigkeit der Beweise sowie deren Bedeutung für den Sachverhalt"}, {"kategorie": "", "text": "Die Beweiswürdigung dient dazu, eine fundierte Grundlage für die [[Urteilsfindung]] zu schaffen"}, {"kategorie": "", "text": "Wesentliche Merkmale der Beweiswürdigung sind: (i) Freiheit der Beweiswürdigung: In Österreich gilt der Grundsatz der freien Beweiswürdigung. Das bedeutet, dass das Gericht nicht an formale Beweisregeln gebunden ist, sondern eigenständig und nach Überzeugung beurteilen kann, welche Beweise es als überzeugend ansieht;  (ii) Glaubwürdigkeit und Beweiskraft: Das Gericht prüft die Qualität der Beweismittel, z. B. die Glaubhaftigkeit von Zeugenaussagen, die Vollständigkeit von Urkunden oder die fachliche Fundierung von Sachverständigengutachten. Dabei wird auch geprüft, ob die Aussagen und Beweismittel in sich widerspruchsfrei sind;  (iii) Verknüpfung der Beweise: Die Beweiswürdigung beinhaltet auch das Zusammensetzen und Abwägen der unterschiedlichen Beweise im Zusammenhang. Das Gericht muss prüfen, ob und wie sich die verschiedenen Beweismittel gegenseitig stützen oder widersprechen;  (iv) Dokumentation: Die Ergebnisse der Beweiswürdigung müssen im Urteil klar und nachvollziehbar dargestellt werden, insbesondere in der [[Urteilsbegründung]], damit ersichtlich ist, auf welcher Grundlage das Gericht seine Entscheidung getroffen hat."}]'::jsonb, ''),
  ('beweisauntrog', 'Beweisauntrog', '', '', '', '', 'Beweisantrag', '[{"kategorie": "jur.", "text": "\"formelles Ersuchen einer [[Prozesspartei]] an das [[Gericht]], im Rahmen eines [[Verfahrens]] bestimmte [[Beweise]] zu erheben, die zur Klärung des Sachverhalts beitragen sollen\""}, {"kategorie": "", "text": "Der Beweisantrag dient dazu, das Gericht auf relevante Beweismittel aufmerksam zu machen, die die Behauptungen oder Einwände der [[Partei]] stützen oder entkräften können"}, {"kategorie": "", "text": "Der Beweisantrag soll das Gericht veranlassen, ein bestimmtes [[Beweismittel]] zu berücksichtigen, wie etwa die Vernehmung eines [[Zeugen]], die Vorlage von Urkunden, ein [[Sachverständigengutachten]] oder eine Ortsbesichtigung (Augenschein)"}, {"kategorie": "", "text": "Ein Beweisantrag muss präzise formuliert sein und in der Regel folgende Punkte enthalten:  (i) Beweismittel: Das konkrete Beweismittel (z. B. Zeuge, Dokument);  (ii) Beweisthema: Die Tatsache, die durch das Beweismittel bewiesen werden soll;  (iii) Gründe: Die Relevanz des Beweismittels für den Sachverhalt oder die Entscheidung des Gerichts"}, {"kategorie": "", "text": "Jede Partei hat das Recht, Beweisanträge zu stellen, um ihren Standpunkt im Verfahren zu stützen. Der Beweisantrag kann sowohl in [[Zivil-]] als auch in [[Strafverfahren]] gestellt werden"}, {"kategorie": "", "text": "Das [[Gericht]] prüft, ob der Beweisantrag zulässig und erforderlich ist. Es kann einen Beweisantrag ablehnen, wenn das Beweismittel für den Fall nicht relevant oder unzulässig ist, wenn die Tatsache bereits als erwiesen gilt, oder wenn der Antrag rechtsmissbräuchlich gestellt wird (z. B. zur Verzögerung des Verfahrens)."}]'::jsonb, ''),
  ('beweisaufnaume', 'Beweisaufnaume', '', '', '', '', 'Beweisaufnahme', '[{"kategorie": "jur.", "text": "\"Prozess, in dem ein [[Gericht]] im Rahmen eines [[Verfahrens]] die relevanten [[Beweise]] sammelt, um den Sachverhalt aufzuklären und eine fundierte Entscheidung zu treffen\""}, {"kategorie": "", "text": "In diesem Verfahrensabschnitt werden alle [[Beweismittel]], die von den Parteien eingebracht oder vom Gericht angeordnet werden, systematisch geprüft und erhoben. Die Beweiserhebung dient dazu, Tatsachen festzustellen, die für die Entscheidung des Gerichts von Bedeutung sind"}, {"kategorie": "", "text": "Es können verschiedene Beweismittel erhoben werden, darunter:  (i) Zeugenaussagen: Personen geben vor Gericht unter [[Wahrheitspflicht]] Auskunft über ihre Wahrnehmungen,  (ii) Sachverständigengutachten: Experten geben ihre fachliche Einschätzung zu bestimmten Fragen ab, die das Gericht nicht selbst beurteilen kann,  (iii) Urkunden: Schriftliche Beweise wie Verträge, Briefe oder amtliche Dokumente,  (iv) Augenschein: Das Gericht besichtigt Orte oder Gegenstände, um sich ein eigenes Bild zu machen,  (v) Parteienvernehmung: Im [[Zivilrecht]] können auch die Parteien selbst als Beweismittel angehört werden"}, {"kategorie": "", "text": "Die Beweiserhebung kann von den [[Parteien]] angeregt werden, indem sie dem Gericht [[Beweisanträge]] stellen. Das Gericht kann auch von Amts wegen Beweise anordnen, wenn es dies zur Sachverhaltsaufklärung für nötig hält"}, {"kategorie": "", "text": "Grundsatz der Mündlichkeit und Unmittelbarkeit: Vor allem in Straf- und Zivilverfahren wird der [[Grundsatz]] der Unmittelbarkeit beachtet, was bedeutet, dass das Gericht die Beweise direkt, beispielsweise durch mündliche Vernehmung der Zeugen oder Experten, erhebt und nicht nur auf schriftliche Berichte zurückgreift"}, {"kategorie": "", "text": "Im Zivilrecht liegt die Beweislast bei der Partei, die etwas behauptet. Sie muss die entsprechenden Beweise vorlegen. Im Strafrecht hingegen liegt die Beweislast in der Regel bei der [[Staatsanwaltschaft]], die die Schuld des Angeklagten nachweisen muss"}, {"kategorie": "", "text": "Die Beweisaufnahme bildet die Grundlage für die anschließende [[Beweiswürdigung]], in der das Gericht die vorgebrachten Beweise auf ihre Glaubwürdigkeit und Relevanz prüft und bewertet, um darauf basierend die Entscheidung im Verfahren zu treffen."}]'::jsonb, ''),
  ('beweiserhebung', 'Beweiserhebung', '', '', '', '', 'Beweiserhebung', '[{"kategorie": "jur.", "text": "\"Prozess, in dem ein [[Gericht]] im Rahmen eines [[Verfahrens]] die relevanten [[Beweise]] sammelt, um den Sachverhalt aufzuklären und eine fundierte Entscheidung zu treffen\""}, {"kategorie": "", "text": "In diesem Verfahrensabschnitt werden alle [[Beweismittel]], die von den Parteien eingebracht oder vom Gericht angeordnet werden, systematisch geprüft und erhoben. Die Beweiserhebung dient dazu, Tatsachen festzustellen, die für die Entscheidung des Gerichts von Bedeutung sind"}, {"kategorie": "", "text": "Es können verschiedene Beweismittel erhoben werden, darunter:  (i) Zeugenaussagen: Personen geben vor Gericht unter [[Wahrheitspflicht]] Auskunft über ihre Wahrnehmungen,  (ii) Sachverständigengutachten: Experten geben ihre fachliche Einschätzung zu bestimmten Fragen ab, die das Gericht nicht selbst beurteilen kann,  (iii) Urkunden: Schriftliche Beweise wie Verträge, Briefe oder amtliche Dokumente,  (iv) Augenschein: Das Gericht besichtigt Orte oder Gegenstände, um sich ein eigenes Bild zu machen,  (v) Parteienvernehmung: Im [[Zivilrecht]] können auch die Parteien selbst als Beweismittel angehört werden"}, {"kategorie": "", "text": "Die Beweiserhebung kann von den [[Parteien]] angeregt werden, indem sie dem Gericht [[Beweisanträge]] stellen. Das Gericht kann auch von Amts wegen Beweise anordnen, wenn es dies zur Sachverhaltsaufklärung für nötig hält"}, {"kategorie": "", "text": "Grundsatz der Mündlichkeit und Unmittelbarkeit: Vor allem in Straf- und Zivilverfahren wird der [[Grundsatz]] der Unmittelbarkeit beachtet, was bedeutet, dass das Gericht die Beweise direkt, beispielsweise durch mündliche Vernehmung der Zeugen oder Experten, erhebt und nicht nur auf schriftliche Berichte zurückgreift"}, {"kategorie": "", "text": "Im Zivilrecht liegt die Beweislast bei der Partei, die etwas behauptet. Sie muss die entsprechenden Beweise vorlegen. Im Strafrecht hingegen liegt die Beweislast in der Regel bei der [[Staatsanwaltschaft]], die die Schuld des Angeklagten nachweisen muss"}, {"kategorie": "", "text": "Die Beweiserhebung bildet die Grundlage für die anschließende [[Beweiswürdigung]], in der das Gericht die vorgebrachten Beweise auf ihre Glaubwürdigkeit und Relevanz prüft und bewertet, um darauf basierend die Entscheidung im Verfahren zu treffen."}]'::jsonb, ''),
  ('uataeusfindung', 'Uatäusfindung', '', '', '', '', 'Urteilsfindung', '[{"kategorie": "jur.", "text": "\"Prozess, in dem ein [[Gericht]] nach der Prüfung von [[Beweisen]], rechtlichen Argumenten und der Auslegung von Gesetzen zu einer Entscheidung über [[Schuld]] oder [[Unschuld]] sowie über die rechtlichen Konsequenzen einer Handlung gelangt\""}, {"kategorie": "", "text": "Die Urteilsfindung bildet den Kern eines gerichtlichen Verfahrens und mündet im endgültigen [[Urteil]], das in einem [[Zivil-]], [[Straf-]] oder [[Verwaltungsverfahren]] ergeht"}, {"kategorie": "", "text": "Wichtige Schritte der Urteilsfindung sind:  (i) [[Beweiserhebung]]: Das Gericht sammelt und prüft alle Beweise, die von den Parteien vorgelegt wurden, wie Zeugenaussagen, Dokumente oder Sachverständigengutachten. Diese Beweise werden bewertet, um festzustellen, welche Tatsachen als bewiesen gelten;  (ii) Beweiswürdigung: In diesem Schritt bewertet das Gericht die Glaubwürdigkeit und Relevanz der Beweise. Es entscheidet, welche Beweise und Aussagen als zuverlässig gelten und wie sie in die Urteilsfindung einfließen;  (iii) Anwendung des Rechts: Das Gericht wendet auf den festgestellten Sachverhalt die einschlägigen Gesetze und Rechtsnormen an. Dabei interpretiert es die Gesetze und prüft, welche Rechtsfolgen sich aus den festgestellten Tatsachen ergeben;  (iv) Berücksichtigung von Argumenten: Die rechtlichen Argumente der Parteien werden vom Gericht sorgfältig abgewogen, und es setzt sich mit den vorgebrachten Positionen auseinander, um zu einer ausgewogenen und rechtlich fundierten Entscheidung zu gelangen;  (v) Schlussfolgerung: Das Gericht gelangt zu einer endgültigen Entscheidung darüber, ob der [[Tatbestand]] einer [[Straftat]], eines zivilrechtlichen Anspruchs oder eines anderen Rechtsverstoßes erfüllt ist. Dies führt zum [[Schuldspruch]] oder [[Freispruch]] im [[Strafrecht]] bzw. zu einer [[Verurteilung]] oder Abweisung im [[Zivilrecht]]"}, {"kategorie": "", "text": "Die Urteilsfindung endet mit der Verkündung des Urteils, das in der Regel aus dem [[Urteilsspruch]] (dem eigentlichen Entscheidungssatz) und einer [[Begründung]] besteht, in der das Gericht seine rechtlichen und tatsächlichen Erwägungen darlegt. Die [[Urteilsbegründung]] ist dabei zentral, um die Entscheidung für die Parteien und mögliche Rechtsmittelinstanzen nachvollziehbar zu machen."}]'::jsonb, ''),
  ('nichtichkeit', 'Nichtichkeit', '', '', '', '', 'Nichtigkeit', '[{"kategorie": "jur.", "text": "\"Zustand, in dem eine Rechtshandlung, insbesondere ein Vertrag, von Anfang an (ex tunc) ungültig ist, weil bestimmte gesetzliche Voraussetzungen nicht erfüllt wurden\""}, {"kategorie": "", "text": "Ein nichtiger Rechtsakt hat keinerlei rechtliche Wirkung, so als wäre er niemals geschlossen worden"}, {"kategorie": "", "text": "Gründe für die Nichtigkeit im Zivilrecht können verschiedene rechtliche Mängel sein, darunter: (i) Verstoß gegen zwingendes Recht: Wenn ein Vertrag gegen gesetzliche Vorschriften verstößt (z. B. gegen das Gesetz oder die guten Sitten), ist er nichtig. Ein Beispiel hierfür wäre ein Vertrag, der auf eine strafbare Handlung abzielt;  (ii) [[Geschäftsunfähigkeit]]: Verträge, die von geschäftsunfähigen Personen (z. B. Kindern unter 7 Jahren oder Personen mit schwerer geistiger Beeinträchtigung) abgeschlossen werden, sind nichtig, es sei denn, es handelt sich um sogenannte [[Taschengeldgeschäfte]] im Rahmen des Alltags;  (iii) [[Formmängel]]: In manchen Fällen ist ein Vertrag nur gültig, wenn er in einer bestimmten Form abgeschlossen wird (z. B. Schriftform, Notariatsakt). Fehlt diese vorgeschriebene Form, kann der Vertrag nichtig sein,  (iv) Fehlende [[Willenserklärung]]: Ein Vertrag ist nichtig, wenn eine der Vertragsparteien keine wirksame Willenserklärung abgegeben hat, etwa weil sie geirrt, bedroht oder getäuscht wurde"}, {"kategorie": "", "text": "Die Nichtigkeit unterscheidet sich von der [[Anfechtbarkeit]] dadurch, dass bei nichtigen Rechtsgeschäften keine Rechtswirkungen eintreten, während bei anfechtbaren Rechtsgeschäften die Möglichkeit besteht, das Geschäft nachträglich für unwirksam zu erklären"}, {"kategorie": "", "text": "Im Strafrecht bezeichnet Nichtigkeit die vollständige Unwirksamkeit eines Urteils oder einer anderen gerichtlichen Entscheidung, weil schwerwiegende rechtliche Fehler vorliegen. Ein nichtiges Urteil hat keine rechtlichen Wirkungen - so als ob es nie ergangen wäre. Anders als anfechtbare Entscheidungen, die durch [[Berufung]] oder [[Revision]] korrigiert werden können, sind nichtige Urteile von Anfang an ungültig"}, {"kategorie": "", "text": "Gründe für die Nichtigkeit eines [[Urteils]] im [[Strafrecht]] können sein:  (i) Verstoß gegen zwingende Verfahrensvorschriften: Wenn wesentliche Regeln des Strafverfahrens verletzt wurden, wie z. B. das Recht auf [[rechtliches]] Gehör, die Unabhängigkeit des Gerichts oder die ordnungsgemäße Besetzung des Gerichts, kann dies zur Nichtigkeit des Urteils führen. Ein Beispiel wäre, wenn das Urteil von einem unzuständigen Gericht erlassen wurde;  (ii) Fehlende [[Begründung]]: Ein Urteil muss nachvollziehbar und rechtsstaatlich begründet sein. Wenn es keine Begründung enthält oder diese gravierende Mängel aufweist, kann dies die Nichtigkeit zur Folge haben;  (iii) Verletzung grundlegender Rechte: Verstöße gegen verfassungsmäßig garantierte Rechte, wie das Recht auf ein [[faires]] Verfahren oder auf Verteidigung, können ein Urteil nichtig machen;  (iv) Unzulässige Rechtsgrundlage: Wenn ein Urteil auf einer Rechtsvorschrift beruht, die in dem Fall nicht anwendbar ist oder gegen höherrangiges Recht (z. B. Verfassungsrecht) verstößt, kann das Urteil nichtig sein."}]'::jsonb, ''),
  ('sochwoita', 'Sochwoita', '', '', '', '', 'Sachwalter', '[{"kategorie": "jur.", "text": "\"Person, die vom Gericht bestellt wurde, um die rechtlichen Angelegenheiten einer volljährigen Person zu regeln, die aufgrund einer psychischen oder geistigen Beeinträchtigung nicht in der Lage war, selbst Entscheidungen zu treffen\""}, {"kategorie": "", "text": "Seit der Reform durch das Erwachsenenschutzgesetz 2018 gibt es den Sachwalter in dieser Form nicht mehr. Stattdessen gibt es nun die gerichtliche [[Erwachsenenvertretung]], die eine ähnliche Funktion erfüllt:  3. Der gerichtliche [[Erwachsenenvertreter]] übernimmt Aufgaben, die der betroffenen Person nicht mehr selbstständig möglich sind, allerdings mit einem stärkeren Fokus auf die Selbstbestimmung der betroffenen Person"}, {"kategorie": "", "text": "Das Ziel der Reform war, die Rechte und die Autonomie von Menschen, die Unterstützung benötigen, zu stärken und nur so viel Eingriff wie notwendig vorzunehmen"}, {"kategorie": "", "text": "Wenn also heute von einem \"Sachwalter\" gesprochen wird, ist in der aktuellen Rechtslage die Rolle des gerichtlichen [[Erwachsenenvertreters]] gemeint, der auf Antrag oder durch gerichtliche Bestellung handelt."}]'::jsonb, ''),
  ('eawochsananvatreta', 'Eawochsananvatreta', '', '', '', '', 'Erwachsenenvertreter', '[{"kategorie": "jur.", "text": "\"Person, die im Rahmen der [[Erwachsenenvertretung]] die rechtlichen Angelegenheiten einer volljährigen Person regelt, die aufgrund einer psychischen, geistigen oder physischen Beeinträchtigung nicht mehr in der Lage ist, diese selbst zu besorgen\""}, {"kategorie": "", "text": "Der Erwachsenenvertreter handelt stellvertretend und unterstützt die betroffene Person, Entscheidungen zu treffen oder übernimmt notwendige rechtliche Handlungen in ihrem Namen"}, {"kategorie": "", "text": "Die Rolle des Erwachsenenvertreters entsteht aus dem österreichischen Erwachsenenschutzgesetz, das seit 2018 gilt und auf dem Prinzip der Selbstbestimmung basiert"}, {"kategorie": "", "text": "Es gibt drei Formen der Erwachsenenvertretung, und je nach Art der Vertretung wird auch der Vertreter unterschiedlich bestimmt:  (i) Gewählter Erwachsenenvertreter: Diese Person wird von der betroffenen Person selbst ausgewählt, solange sie noch entscheidungsfähig ist. Der gewählte Vertreter übernimmt die Vertretung, wenn die Person nicht mehr selbstständig handeln kann;  (ii) Gesetzlicher Erwachsenenvertreter: Ist keine gewählte Vertretung vorhanden, können nahe Angehörige (z. B. Ehepartner, Kinder) automatisch als gesetzliche Erwachsenenvertreter fungieren. Sie müssen sich ins Österreichische Zentrale Vertretungsverzeichnis (ÖZVV) eintragen lassen;  (iii) Gerichtlicher Erwachsenenvertreter: Falls keine gewählte oder gesetzliche Vertretung besteht, bestellt das Gericht einen Erwachsenenvertreter, der die Interessen der betroffenen Person wahrnimmt. Dies kann eine private Person oder eine Vertretungsorganisation sein"}, {"kategorie": "", "text": "Ein Erwachsenenvertreter ist verpflichtet, im besten Interesse der betroffenen Person zu handeln und deren Wünsche und Bedürfnisse – soweit möglich – zu berücksichtigen. Die Vertretung ist auf bestimmte Aufgabenbereiche beschränkt und soll nur das regeln, was die betroffene Person nicht mehr selbst entscheiden kann."}]'::jsonb, ''),
  ('eawochsananvatretung', 'Eawochsananvatretung', '', '', '', '', 'Erwachsenenvertretung', '[{"kategorie": "jur.", "text": "\"ein im österreichischen Recht geregeltes Instrument, das Personen unterstützt, die aufgrund von geistigen, psychischen oder physischen Beeinträchtigungen nicht mehr in der Lage sind, ihre Angelegenheiten selbstständig zu regeln\""}, {"kategorie": "", "text": "Die Erwachsenenvertretung wurde durch das Erwachsenenschutzgesetz 2018 eingeführt und ersetzt das frühere Sachwalterschaftssystem. Ziel ist es, den Betroffenen möglichst viel Selbstbestimmung zu ermöglichen und nur so viel Hilfe wie nötig bereitzustellen"}, {"kategorie": "", "text": "Es gibt verschiedene Formen der Erwachsenenvertretung, die je nach Grad der Selbstbestimmungsfähigkeit der betroffenen Person abgestuft sind: (i) Gewählte Erwachsenenvertretung: Eine Person kann im Voraus jemanden bestimmen, der im Bedarfsfall ihre rechtlichen Angelegenheiten regeln soll. Diese Form setzt voraus, dass die betroffene Person noch entscheidungsfähig ist, wenn sie die Vertretung wählt;  (ii) Gesetzliche Erwachsenenvertretung: Hier übernimmt ein naher Angehöriger (z. B. Ehepartner, Kinder) die Vertretung, wenn keine gewählte Vertretung vorhanden ist und die betroffene Person keine eigene Entscheidung treffen kann. Die gesetzlichen Vertreter müssen ins Österreichische Zentrale Vertretungsverzeichnis (ÖZVV) eingetragen werden;  (iii) Gerichtliche Erwachsenenvertretung: Diese Form wird vom [[Gericht]] angeordnet, wenn weder eine gewählte noch eine gesetzliche Vertretung vorhanden ist. Das Gericht bestimmt dann eine geeignete Person oder eine Organisation zur Vertretung"}, {"kategorie": "", "text": "Die Erwachsenenvertretung soll immer nur für jene Angelegenheiten gelten, die der Betroffene nicht selbst regeln kann, und ist auf das notwendige Maß beschränkt. Sie dient dem Schutz der Rechte und Interessen von Erwachsenen, die Unterstützung bei der Ausübung ihrer rechtlichen Handlungsfähigkeit benötigen."}]'::jsonb, ''),
  ('gschaeftsunfaehigkeit', 'Gschäftsunfähigkeit', '', '', '', '', 'Geschäftsunfähigkeit', '[{"kategorie": "jur.", "text": "\"Zustand, in dem eine Person nicht in der Lage ist, rechtswirksame Willenserklärungen abzugeben und somit keine rechtlich bindenden Geschäfte abschließen kann\""}, {"kategorie": "", "text": "In Österreich gilt eine Person als geschäftsunfähig, wenn sie entweder aufgrund ihres Alters oder wegen einer dauerhaften geistigen Beeinträchtigung nicht in der Lage ist, die Bedeutung und Konsequenzen von rechtlichen Handlungen zu verstehen"}, {"kategorie": "", "text": "Es gibt zwei Hauptkategorien der Geschäftsunfähigkeit: (i) Kinder unter 7 Jahren sind generell geschäftsunfähig. Sie können keine rechtswirksamen Verträge abschließen, außer in Fällen von sogenannten \"Taschengeldgeschäften\", bei denen sie sofort einen geringfügigen Vorteil erlangen (z. B. Kauf eines kleinen Gegenstands);  (ii) Personen, die aufgrund einer psychischen oder geistigen Beeinträchtigung dauerhaft nicht in der Lage sind, die Folgen ihrer Handlungen zu überblicken, gelten ebenfalls als geschäftsunfähig. In solchen Fällen kann ein gerichtlicher [[Sachwalter]] oder ein [[Erwachsenenvertreter]] bestellt werden, um die rechtlichen Interessen der betroffenen Person zu wahren"}, {"kategorie": "", "text": "Geschäftsunfähige Personen können keine rechtsverbindlichen Verträge schließen, und von ihnen abgegebene Willenserklärungen sind in der Regel nichtig."}]'::jsonb, ''),
  ('gschaeftsfaehigkeit', 'Gschäftsfähigkeit', '', '', '', '', 'Geschäftsfähigkeit', '[{"kategorie": "jur.", "text": "\"Fähigkeit einer Person, rechtswirksame Willenserklärungen abzugeben und somit selbstständig am Rechtsverkehr teilzunehmen, das heißt, Verträge zu schließen oder andere rechtliche Handlungen vorzunehmen\""}, {"kategorie": "", "text": "Die Geschäftsfähigkeit ist ein wichtiger Aspekt des [[Zivilrechts]] und bestimmt, ab welchem Alter oder unter welchen Umständen eine Person rechtlich bindende Geschäfte abschließen kann"}, {"kategorie": "", "text": "In Österreich wird die Geschäftsfähigkeit in verschiedene Stufen unterteilt: (i) Geschäftsunfähigkeit: Kinder unter 7 Jahren sind grundsätzlich geschäftsunfähig. Sie können keine rechtswirksamen Verträge abschließen, außer sie erlangen durch geringfügige, alltägliche Geschäfte (z. B. Kauf eines Schokoriegels) sofort einen Vorteil;  (ii) Beschränkte Geschäftsfähigkeit: Minderjährige zwischen 7 und 14 Jahren können ebenfalls nur beschränkt Geschäfte tätigen, die ihnen ausschließlich rechtlichen Vorteil bringen oder die mit Zustimmung der Eltern erfolgen. Zwischen 14 und 18 Jahren dürfen Jugendliche bereits weitergehende Verträge abschließen, benötigen aber ebenfalls oft die Zustimmung der gesetzlichen Vertreter, vor allem bei größeren Geschäften;  (iii) Volle Geschäftsfähigkeit: Ab dem 18. Lebensjahr ist eine Person in Österreich grundsätzlich voll geschäftsfähig und kann ohne Einschränkungen Verträge abschließen"}, {"kategorie": "", "text": "Personen, die aufgrund einer geistigen oder psychischen Beeinträchtigung dauerhaft nicht in der Lage sind, die Folgen ihrer Handlungen zu verstehen, können ebenfalls geschäftsunfähig oder beschränkt geschäftsfähig sein. In solchen Fällen wird eine gerichtliche Betreuung oder Vertretung angeordnet."}]'::jsonb, ''),
  ('unzurechnungsfaehigkeit', 'Unzurechnungsfähigkeit', '', '', '', '', 'Unzurechnungsfähigkeit', '[{"kategorie": "jur.", "text": "\"Zustand, in dem eine Person aufgrund einer schweren psychischen Störung, geistigen Behinderung oder tiefgreifenden Bewusstseinsstörung nicht in der Lage ist, das Unrecht einer Handlung zu erkennen oder entsprechend dieser Einsicht zu handeln\""}, {"kategorie": "", "text": "Eine solche Person kann für ihre Tat nicht strafrechtlich verantwortlich gemacht werden, da ihr das notwendige Verständnis für das Unrecht und die Kontrolle über ihr Verhalten fehlt"}, {"kategorie": "", "text": "In Österreich ist die Unzurechnungsfähigkeit in § 11 des [[Strafgesetzbuches]] (StGB) geregelt. Sie tritt dann ein, wenn eine krankhafte Störung der Geistestätigkeit, eine tiefgreifende Bewusstseinsstörung oder eine geistige Behinderung vorliegt, die dazu führt, dass der Täter entweder das Unrecht seiner Handlung nicht erkennen oder nicht nach dieser Einsicht handeln konnte"}, {"kategorie": "", "text": "In diesen Fällen entfällt die strafrechtliche Schuld, und der Betroffene kann nicht bestraft werden"}, {"kategorie": "", "text": "Statt einer [[Strafe]] kann jedoch, wenn der [[Täter]] eine Gefahr für die Allgemeinheit darstellt, eine Unterbringung in einer psychiatrischen Einrichtung angeordnet werden."}]'::jsonb, ''),
  ('zurechnungsfaehigkeit', 'Zurechnungsfähigkeit', '', '', '', '', 'Zurechnungsfähigkeit', '[{"kategorie": "jur.", "text": "\"Fähigkeit einer Person, das Unrecht einer [[Tat]] einzusehen und nach dieser Einsicht zu handeln\""}, {"kategorie": "", "text": "Sie ist eine wesentliche Voraussetzung für die strafrechtliche Verantwortlichkeit. Eine Person ist nur dann strafrechtlich zur Verantwortung zu ziehen, wenn sie im Zeitpunkt der Tat zurechnungsfähig war"}, {"kategorie": "", "text": "Gemäß § 11 des [[österreichischen]] Strafgesetzbuches (StGB) ist eine Person unzurechnungsfähig, wenn sie aufgrund einer krankhaften Störung der Geistestätigkeit, einer tiefgreifenden Bewusstseinsstörung oder einer geistigen Behinderung nicht in der Lage war, das Unrecht ihrer Tat zu erkennen oder nach dieser Einsicht zu handeln. In solchen Fällen kann die Person nicht bestraft werden, da ihr die Schuld im strafrechtlichen Sinne fehlt"}, {"kategorie": "", "text": "Zurechnungsfähigkeit ist also der Zustand, in dem jemand geistig und psychisch in der Lage ist, eine [[Straftat]] zu erkennen und zu verhindern"}, {"kategorie": "", "text": "Liegt eine [[Unzurechnungsfähigkeit]] vor, greift statt einer Strafe oft eine Unterbringung in einer Anstalt für geistig abnorme Rechtsbrecher, wenn eine Gefahr für die Allgemeinheit besteht."}]'::jsonb, ''),
  ('unschuid', 'Unschuid', '', '', '', '', 'Unschuld', '[{"kategorie": "jur.", "text": "\"Zustand, in dem eine Person nicht für eine [[strafbare]] Handlung verantwortlich ist oder keine [[Schuld]] im Sinne des [[Strafrechts]] auf sich geladen hat\""}, {"kategorie": "", "text": "Das bedeutet, dass die betreffende Person entweder die [[Tat]] nicht begangen hat oder, falls sie die Tat begangen hat, keine strafrechtliche Verantwortung dafür trägt"}, {"kategorie": "", "text": "Unschuld wird in einem [[Strafverfahren]] solange angenommen, bis die Schuld des Angeklagten anhand von [[Beweisen]] nachgewiesen wurde"}, {"kategorie": "", "text": "Die [[Unschuldsvermutung]] bildet einen zentralen Grundsatz des [[Rechtsstaates]]: Jede Person gilt als unschuldig, bis ihre Schuld zweifelsfrei vor Gericht festgestellt wurde"}, {"kategorie": "", "text": "Die Feststellung der Unschuld erfolgt durch einen [[Freispruch]], wenn das Gericht zu dem Ergebnis kommt, dass der [[Angeklagte]] die ihm vorgeworfene Tat nicht begangen hat oder keine strafrechtliche Verantwortung besteht."}]'::jsonb, ''),
  ('schuid', 'Schuid', '', '', '', '', 'Schuld', '[{"kategorie": "jur.", "text": "\"individuelle Verantwortlichkeit einer Person für eine [[strafbare]] Handlung\""}, {"kategorie": "", "text": "Diese liegt vor, wenn jemand eine Tat mit [[Vorsatz]] oder aus [[Fahrlässigkeit]] begangen hat und dabei in der Lage war, das Unrecht seiner Handlung zu erkennen und entsprechend zu handeln"}, {"kategorie": "", "text": "Um Schuld festzustellen, müssen folgende Elemente geprüft werden: (i) [[Tatbestand]]: Der Täter hat den gesetzlichen [[Straftatbestand]] erfüllt;  (ii) Rechtswidrigkeit: Die Handlung war rechtswidrig, also nicht durch gesetzliche Rechtfertigungsgründe (wie [[Notwehr]]) gedeckt;  (iii) Schuldhaftigkeit: Der Täter handelte schuldhaft, das heißt, er konnte das Unrecht seiner Tat einsehen und sich entsprechend dieser Einsicht verhalten"}, {"kategorie": "", "text": "Schuld ist eine Grundvoraussetzung für die strafrechtliche [[Verurteilung]] und bedeutet, dass dem Täter die strafbare Handlung persönlich vorwerfbar ist"}, {"kategorie": "", "text": "Ohne Schuld entfällt die Möglichkeit, eine Strafe zu verhängen."}]'::jsonb, ''),
  ('begruendung', 'Begründung', '', '', '', '', 'Begründung', '[{"kategorie": "jur.", "text": "\"nachvollziehbare Erklärung oder Darlegung von Gründen, die einer Entscheidung, Handlung oder Ansicht zugrunde liegen\""}, {"kategorie": "", "text": "Die Begründung dient dazu, den Sachverhalt verständlich zu machen und zu rechtfertigen, warum eine bestimmte Entscheidung getroffen oder eine bestimmte Position eingenommen wurde"}, {"kategorie": "", "text": "In einem rechtlichen Kontext, wie bei [[Gerichtsurteilen]], ist die Begründung der Teil, in dem ein Gericht erläutert, auf welchen rechtlichen und tatsächlichen Erwägungen das [[Urteil]] basiert (siehe [[Urteilsbegründung]])"}, {"kategorie": "", "text": "Ziel einer Begründung ist es, Transparenz zu schaffen, damit die Entscheidung oder Handlung logisch und nachvollziehbar erscheint."}]'::jsonb, ''),
  ('schdrofuataeu', 'Schdrofuatäu', '', '', '', '', 'Strafurteil', '[{"kategorie": "jur.", "text": "\"förmliche Entscheidung eines [[Gerichts]] in einem [[Strafverfahren]], das über die [[Schuld]] oder [[Unschuld]] des [[Angeklagten]] sowie die Höhe der [[Strafe]] entscheidet, falls eine [[Verurteilung]] erfolgt\""}, {"kategorie": "", "text": "Das Strafurteil besteht aus zwei Hauptteilen: dem [[Schuldspruch]] oder [[Freispruch]], der feststellt, ob der Angeklagte die ihm zur Last gelegte [[Straftat]] begangen hat, und dem [[Strafausspruch]], der das [[Strafmaß]] festlegt, falls der Angeklagte schuldig gesprochen wird"}, {"kategorie": "", "text": "Das Strafurteil umfasst dabei sowohl die rechtliche [[Begründung]] als auch die Feststellungen zu den Tatsachen des Falls. Es ist verbindlich und bildet die Grundlage für die Vollstreckung der Strafe"}, {"kategorie": "", "text": "[[Parteien]] im Verfahren können gegen das Strafurteil [[Rechtsmittel]] wie [[Berufung]] oder [[Revision]] einlegen, um eine Überprüfung durch ein höheres Gericht zu erreichen."}]'::jsonb, ''),
  ('veruataeuta', 'Veruatäuta', '', '', '', '', 'Verurteilter', '[{"kategorie": "jur.", "text": "\"Person, die in einem gerichtlichen [[Strafverfahren]] für schuldig befunden wurde und gegen die ein [[Strafurteil]] ergangen ist\""}, {"kategorie": "", "text": "Das [[Gericht]] hat nach Prüfung der [[Beweise]] entschieden, dass die Person eine [[Straftat]] begangen hat, und sie somit rechtlich verantwortlich gemacht"}, {"kategorie": "", "text": "Der Verurteilte muss die im [[Urteil]] festgelegte [[Strafe]], wie zum Beispiel eine [[Geldstrafe]] oder [[Freiheitsstrafe]], tragen"}, {"kategorie": "", "text": "Der Begriff unterscheidet den Verurteilten von einer Person, die freigesprochen wurde oder gegen die das Verfahren noch nicht abgeschlossen ist."}]'::jsonb, ''),
  ('schdrofmooss', 'Schdrofmooss', '', '', '', '', 'Strafmaß', '[{"kategorie": "jur.", "text": "\"die konkrete Höhe oder Art der [[Strafe]], die ein [[Gericht]] nach einem [[Schuldspruch]] gegen einen [[Verurteilten]] verhängt\""}, {"kategorie": "", "text": "Das Strafmaß wird im [[Urteil]] festgelegt und kann verschiedene Formen annehmen, wie zum Beispiel eine [[Geldstrafe]], eine [[Freiheitsstrafe]] oder [[Bewährungsstrafen]]"}, {"kategorie": "", "text": "Das Strafmaß hängt von der Schwere der begangenen Straftat, den Umständen des Falles und den persönlichen Verhältnissen des Täters ab. Dabei berücksichtigt das Gericht sowohl [[strafmildernde]] als auch [[strafverschärfende]] Umstände, wie etwa das Vorliegen von [[Vorstrafen]] oder eine geständige Einlassung des Angeklagten ([[Geständnis]])"}, {"kategorie": "", "text": "Ziel ist es, eine gerechte und verhältnismäßige Strafe zu bestimmen."}]'::jsonb, ''),
  ('schuidschbruch', 'Schuidschbruch', '', '', '', '', 'Schuldspruch', '[{"kategorie": "jur.", "text": "\"gerichtliche Entscheidung, in der festgestellt wird, dass der [[Angeklagte]] eine [[Straftat]] begangen hat und somit schuldig ist\""}, {"kategorie": "", "text": "Im Rahmen eines [[Strafverfahrens]] bedeutet der Schuldspruch, dass das Gericht nach Prüfung der Beweise und der rechtlichen Situation zu dem Ergebnis kommt, dass der Angeklagte für die zur Last gelegte Tat verantwortlich ist"}, {"kategorie": "", "text": "Der Schuldspruch bildet die Grundlage für das anschließende [[Strafmaß]], das in einem weiteren Teil des [[Urteils]], dem sogenannten Strafausspruch, festgelegt wird"}, {"kategorie": "", "text": "Der Schuldspruch bestätigt also die Schuld des Angeklagten und führt zu einer strafrechtlichen [[Verurteilung]]."}]'::jsonb, ''),
  ('freischbruch', 'Freischbruch', '', '', '', '', 'Freispruch', '[{"kategorie": "jur.", "text": "\"gerichtliche Entscheidung, bei der eine angeklagte Person vom Vorwurf einer [[Straftat]] entlastet wird\""}, {"kategorie": "", "text": "Das [[Gericht]] stellt im [[Urteil]] fest, dass entweder die Tat nicht nachgewiesen werden konnte oder die Handlung der angeklagten Person nicht strafbar ist"}, {"kategorie": "", "text": "Ein Freispruch bedeutet, dass der Angeklagte als unschuldig gilt und keine strafrechtlichen Konsequenzen zu tragen hat"}, {"kategorie": "", "text": "Ein Freispruch kann aus verschiedenen Gründen erfolgen, beispielsweise wegen mangelnder Beweise, eines rechtfertigenden Notstands oder weil die Tat nicht den gesetzlichen [[Tatbestand]] einer Straftat erfüllt."}]'::jsonb, ''),
  ('uataeusbegruendung', 'Uatäusbegründung', '', '', '', '', 'Urteilsbegründung', '[{"kategorie": "jur.", "text": "\"Teil eines [[Gerichtsurteils]], in dem das Gericht seine Entscheidung rechtlich und sachlich begründet\""}, {"kategorie": "", "text": "Die Urteilsbegründung ist ein wesentlicher Bestandteil eines Gerichtsurteils und dient dazu, die Entscheidung des Gerichts transparent und nachvollziehbar zu machen"}, {"kategorie": "", "text": "In der Urteilsbegründung erklärt das Gericht, wie es die vorgelegten Beweise bewertet hat und welche Rechtsvorschriften oder -grundsätze dabei angewendet wurden"}, {"kategorie": "", "text": "In der Urteilsbegründung setzt sich das Gericht auch mit den Argumenten und Anträgen der Prozessparteien auseinander. Es erklärt, warum es bestimmten Argumenten folgt und andere zurückweist. Dies ist besonders wichtig, damit die unterlegene Partei versteht, warum ihre Argumente nicht durchgedrungen sind"}, {"kategorie": "", "text": "Die Urteilsbegründung folgt typischerweise auf die Urteilsformel, in der das Gericht das Ergebnis des Verfahrens (z. B. [[Freispruch]], [[Verurteilung]] oder Abweisung einer [[Klage]]) verkündet."}]'::jsonb, ''),
  ('schdrofrauman', 'Schdrofrauman', '', '', '', '', 'Strafrahmen', '[{"kategorie": "jur.", "text": "\"das vom Gesetz vorgegebene Mindest- und Höchstmaß einer [[Strafe]], die für eine bestimmte [[Straftat]] verhängt werden kann\""}, {"kategorie": "", "text": "Der Strafrahmen legt fest, in welchem Umfang ein Gericht die Strafe bemessen darf. Innerhalb dieses Rahmens entscheidet das Gericht im Rahmen der [[Strafzumessung]], wie hoch die konkrete Strafe im Einzelfall ausfällt, abhängig von den individuellen Umständen der Tat und des Täters"}, {"kategorie": "", "text": "Der Strafrahmen ist im [[österreichischen]] Strafgesetzbuch (StGB) und in anderen strafrechtlichen Gesetzen festgelegt. Jede Straftat hat einen definierten Strafrahmen, der als Orientierung für die Gerichte dient. Dieser Rahmen gibt an, welche Mindest- und Höchststrafe verhängt werden darf"}, {"kategorie": "", "text": "Der Strafrahmen enthält in der Regel eine Untergrenze und eine Obergrenze der Strafe. Innerhalb des vorgegebenen Strafrahmens hat das Gericht einen [[Ermessensspielraum]], um die Strafe an die Schwere der Tat, die Schuld des Täters und die individuellen Umstände anzupassen. Faktoren wie [[Milderungsgründe]] und [[Erschwerungsgründe]] beeinflussen dabei, ob das [[Gericht]] eine Strafe näher am unteren oder oberen Ende des Strafrahmens wählt"}, {"kategorie": "", "text": "Beispiele für Strafrahmen:  (i) Leichte Körperverletzung: bis zu 1 Jahr Freiheitsstrafe oder Geldstrafe (§ 83 StGB);  (ii) Schwere Körperverletzung: 1 bis 10 Jahre Freiheitsstrafe (§ 84 StGB);  (iii) Mord: bis zu lebenslanger Freiheitsstrafe (§ 75 StGB)."}]'::jsonb, ''),
  ('schdrofzumessung', 'Schdrofzumessung', '', '', '', '', 'Strafzumessung', '[{"kategorie": "jur.", "text": "\"rechtlicher Prozess, bei dem ein Gericht nach einer Verurteilung die Höhe und Art der Strafe bestimmt, die einem Schuldigen für die begangene [[Straftat]] auferlegt wird\""}, {"kategorie": "", "text": "Die Strafzumessung ist im [[österreichischen]] Strafgesetzbuch (StGB) geregelt. Sie erfolgt immer innerhalb des gesetzlichen [[Strafrahmens]], den das StGB für die jeweilige Straftat vorsieht"}, {"kategorie": "", "text": "Bei der Strafzumessung berücksichtigt das Gericht sowohl die Schwere der Tat als auch die Persönlichkeit und Lebensumstände des Täters. Dazu zählen: (i) [[Erschwerungsgründe]]: Umstände, die die Tat schwerwiegender erscheinen lassen, wie z. B. Rückfälligkeit, besondere Brutalität oder das Ausnutzen einer Vertrauensstellung;  (ii) [[Milderungsgründe]]: Umstände, die die Schuld des Täters mindern, wie z. B. Reue, ein Geständnis, Schadenswiedergutmachung oder ein bislang straffreies Leben"}, {"kategorie": "", "text": "Diese Faktoren werden gegeneinander abgewogen, um die angemessene Strafe zu bestimmen"}, {"kategorie": "", "text": "Das StGB legt für jede Straftat einen [[Strafrahmen]] fest, innerhalb dessen sich die [[Strafe]] bewegen muss. Der Strafrahmen gibt sowohl das Mindestmaß als auch das Höchstmaß der Strafe vor (z. B. Freiheitsstrafe von 1 bis 10 Jahren).\nInnerhalb dieses Rahmens legt das Gericht die Strafe fest, abhängig von den tat- und täterbezogenen Umständen"}, {"kategorie": "", "text": "Ein zentraler Grundsatz der Strafzumessung ist die Verhältnismäßigkeit. Die Strafe muss der Schwere der Tat und der Schuld des Täters angemessen sein. Eine zu harte oder zu milde Strafe wäre ungerecht und könnte angefochten werden"}, {"kategorie": "", "text": "Das [[Gericht]] kann verschiedene Arten von Strafen verhängen, je nach Schwere der Straftat und den Umständen:  (i) Freiheitsstrafe: Haftstrafe in einer [[Justizanstalt]];  (ii) Geldstrafe: Zahlung eines bestimmten Betrags an den [[Staat]];  (iii) Bedingte Strafe: Aussetzung der Strafe zur [[Bewährung]], unter bestimmten Auflagen;  (iv) Nebenstrafen: Einschränkungen wie Berufsverbote oder Fahrverbote"}, {"kategorie": "", "text": "Bei der Strafzumessung gilt das Schuldprinzip: Der Täter wird nur nach dem Maß seiner persönlichen Schuld bestraft. Es wird also nicht nur die Tat selbst, sondern auch der individuelle Tatbeitrag und das Fehlverhalten des Täters bewertet"}, {"kategorie": "", "text": "Das [[Gericht]] muss die Strafzumessung in seinem Urteil begründen. Es muss darlegen, welche [[mildernden]] oder [[erschwerenden]] Umstände es berücksichtigt hat und wie diese die Strafe beeinflusst haben"}, {"kategorie": "", "text": "Gegen eine Strafzumessung kann der Verurteilte [[Rechtsmittel]] einlegen, z. B. [[Berufung]] oder [[Revision]], wenn er der Meinung ist, dass die Strafe unangemessen oder fehlerhaft bemessen wurde."}]'::jsonb, ''),
  ('schdrofbemessung', 'Schdrofbemessung', '', '', '', '', 'Strafbemessung', '[{"kategorie": "jur.", "text": "\"rechtlicher Prozess, bei dem ein Gericht nach einer Verurteilung die Höhe und Art der Strafe bestimmt, die einem Schuldigen für die begangene [[Straftat]] auferlegt wird\""}, {"kategorie": "", "text": "Die Strafzumessung ist im [[österreichischen]] Strafgesetzbuch (StGB) geregelt. Sie erfolgt immer innerhalb des gesetzlichen [[Strafrahmens]], den das StGB für die jeweilige Straftat vorsieht"}, {"kategorie": "", "text": "Bei der Strafzumessung berücksichtigt das Gericht sowohl die Schwere der Tat als auch die Persönlichkeit und Lebensumstände des Täters. Dazu zählen: (i) [[Erschwerungsgründe]]: Umstände, die die Tat schwerwiegender erscheinen lassen, wie z. B. Rückfälligkeit, besondere Brutalität oder das Ausnutzen einer Vertrauensstellung;  (ii) [[Milderungsgründe]]: Umstände, die die Schuld des Täters mindern, wie z. B. Reue, ein Geständnis, Schadenswiedergutmachung oder ein bislang straffreies Leben"}, {"kategorie": "", "text": "Diese Faktoren werden gegeneinander abgewogen, um die angemessene Strafe zu bestimmen"}, {"kategorie": "", "text": "Das StGB legt für jede Straftat einen [[Strafrahmen]] fest, innerhalb dessen sich die [[Strafe]] bewegen muss. Der Strafrahmen gibt sowohl das Mindestmaß als auch das Höchstmaß der Strafe vor (z. B. Freiheitsstrafe von 1 bis 10 Jahren).\nInnerhalb dieses Rahmens legt das Gericht die Strafe fest, abhängig von den tat- und täterbezogenen Umständen"}, {"kategorie": "", "text": "Ein zentraler Grundsatz der Strafzumessung ist die Verhältnismäßigkeit. Die Strafe muss der Schwere der Tat und der Schuld des Täters angemessen sein. Eine zu harte oder zu milde Strafe wäre ungerecht und könnte angefochten werden"}, {"kategorie": "", "text": "Das [[Gericht]] kann verschiedene Arten von Strafen verhängen, je nach Schwere der Straftat und den Umständen:  (i) Freiheitsstrafe: Haftstrafe in einer [[Justizanstalt]];  (ii) Geldstrafe: Zahlung eines bestimmten Betrags an den [[Staat]];  (iii) Bedingte Strafe: Aussetzung der Strafe zur [[Bewährung]], unter bestimmten Auflagen;  (iv) Nebenstrafen: Einschränkungen wie Berufsverbote oder Fahrverbote"}, {"kategorie": "", "text": "Bei der Strafzumessung gilt das Schuldprinzip: Der Täter wird nur nach dem Maß seiner persönlichen Schuld bestraft. Es wird also nicht nur die Tat selbst, sondern auch der individuelle Tatbeitrag und das Fehlverhalten des Täters bewertet"}, {"kategorie": "", "text": "Das [[Gericht]] muss die Strafzumessung in seinem Urteil begründen. Es muss darlegen, welche [[mildernden]] oder [[erschwerenden]] Umstände es berücksichtigt hat und wie diese die Strafe beeinflusst haben"}, {"kategorie": "", "text": "Gegen eine Strafzumessung kann der Verurteilte [[Rechtsmittel]] einlegen, z. B. [[Berufung]] oder [[Revision]], wenn er der Meinung ist, dass die Strafe unangemessen oder fehlerhaft bemessen wurde."}]'::jsonb, ''),
  ('erschwerungsgruende', 'Erschwerungsgründe', '', '', '', '', 'Erschwerungsgründe', '[{"kategorie": "jur.", "text": "\"Faktoren, die bei der Strafzumessung berücksichtigt werden und dazu führen, dass die Strafe für den Täter erhöht wird\""}, {"kategorie": "", "text": "Erschwerungsgründe sind das Gegenstück zu den [[Milderungsgründen]] und zielen darauf ab, die Schwere der Tat und das Verhalten des Täters in den Vordergrund zu stellen"}, {"kategorie": "", "text": "Erschwerungsgründe sind im [[österreichischen]] Strafgesetzbuch (StGB) geregelt. Bei der [[Strafzumessung]] ist das Gericht verpflichtet, sowohl [[erschwerende]] als auch [[mildernde]] Umstände zu berücksichtigen, um eine angemessene Strafe zu verhängen"}, {"kategorie": "", "text": "Beispiele für Erschwerungsgründe: (i) Wiederholungsgefahr: Wenn der Täter bereits wegen ähnlicher Straftaten verurteilt wurde oder als Rückfalltäter gilt, wirkt dies erschwerend;  (ii) Planung und [[Vorsatz]]: Eine Tat, die geplant oder mit besonderem Vorsatz durchgeführt wurde, wird als schwerwiegender angesehen als eine spontane Tat;  (iii) Tatbegehung mit besonderer Brutalität oder Grausamkeit: Eine besonders brutale oder grausame Ausführung der Tat verschärft die Strafe;  (iv) Beteiligung an einer [[kriminellen]] Vereinigung: Wenn der Täter als Teil einer kriminellen Organisation handelt oder gemeinsam mit mehreren Tätern, gilt dies als erschwerend;  (v) Ausnutzung einer Vertrauensstellung: Wenn der Täter eine Vertrauensstellung (z. B. als Betreuer, Lehrer, oder in einem Abhängigkeitsverhältnis) ausnutzt, wird dies als Erschwerungsgrund gewertet;  (vi) Schwere Folgen der Tat: Wenn die Straftat besonders schwere Folgen für das Opfer hat (z. B. schwere körperliche oder seelische Schäden), kann dies die Strafe erhöhen;  (vii) Besondere Rücksichtslosigkeit: Wenn der Täter bei der Tat eine besondere Rücksichtslosigkeit oder Gefährdung anderer Menschen gezeigt hat"}, {"kategorie": "", "text": "Erschwerungsgründe führen in der Regel dazu, dass die Strafe im Rahmen des gesetzlich vorgesehenen Strafrahmens erhöht wird. Bei besonders schwerwiegenden Erschwerungsgründen kann die Strafe an der Obergrenze des vorgesehenen Strafmaßes liegen."}]'::jsonb, ''),
  ('miuedarungsgruende', 'Miüdarungsgründe', '', '', '', '', 'Milderungsgründe', '[{"kategorie": "jur.", "text": "\"Faktoren, die bei der [[Strafzumessung]] berücksichtigt werden, um die Strafe für den [[Angeklagten]] zu mildern\""}, {"kategorie": "", "text": "Sie zielen darauf ab, den individuellen Umständen des [[Täters]] und der Tat Rechnung zu tragen und können dazu führen, dass das Gericht eine geringere Strafe verhängt, als sie für die begangene [[Straftat]] im [[Gesetz]] vorgesehen ist"}, {"kategorie": "", "text": "Milderungsgründe sind im [[österreichischen]] Strafgesetzbuch (StGB) verankert. Das Gericht ist verpflichtet, bei der Strafbemessung sowohl [[erschwerende]] als auch [[mildernde]] Umstände zu berücksichtigen, um eine gerechte Strafe zu verhängen"}, {"kategorie": "", "text": "Beispiele für Milderungsgründe: (i) Reue: Der Täter zeigt nach der Tat aufrichtige Reue und bemüht sich, den verursachten Schaden wiedergutzumachen;  (ii) Geständnis: Ein frühzeitiges und umfassendes Geständnis kann als Milderungsgrund gelten, da es dem Verfahren Zeit und Kosten spart und dem Täter Verantwortungsbewusstsein zuschreibt;  (iii) Täter ist Ersttäter: Wenn der Täter bisher nicht straffällig geworden ist, kann dies als Milderungsgrund angesehen werden;  (iv) Geringes Verschulden: Liegt nur eine geringe Schuld vor, z. B. bei geringerem [[Vorsatz]] oder [[Fahrlässigkeit]], kann dies strafmildernd wirken;  (v) Notlage: Handelte der Täter aus einer wirtschaftlichen oder sozialen Notlage heraus, kann dies als Milderungsgrund gelten;  (vi) Lange Verfahrensdauer: Wenn ein Strafverfahren übermäßig lange dauert, kann dies als Milderungsgrund bei der Strafzumessung berücksichtigt werden;  (vii) Provokation durch das Opfer: Eine Handlung unter starker emotionaler Belastung oder Provokation durch das Opfer kann die Strafe mildern"}, {"kategorie": "", "text": "Milderungsgründe führen in der Regel dazu, dass das Gericht eine niedrigere Strafe innerhalb des gesetzlich vorgesehenen Strafrahmens verhängt. Bei besonders vielen oder starken Milderungsgründen kann das Gericht auch eine [[bedingte]] Strafe oder [[Bewährung]] aussprechen."}]'::jsonb, ''),
  ('schdrof', 'Schdrof', '', '', '', '', 'Strafe', '[{"kategorie": "jur.", "text": "\" staatlich verhängte Sanktion, die als Reaktion auf die Begehung einer [[Straftat]] oder eines [[Vergehens]] ausgesprochen wird\""}, {"kategorie": "", "text": "Strafen dienen dazu, den Rechtsfrieden wiederherzustellen, Unrecht zu ahnden und in der Regel auch zur Abschreckung zukünftiger Straftaten beizutragen"}, {"kategorie": "", "text": "Strafen basieren auf gesetzlichen Vorschriften, die im österreichischen [[Strafgesetzbuch]] (StGB) oder anderen rechtlichen Normen festgelegt sind. Sie dürfen nur aufgrund einer rechtskräftigen Entscheidung eines Gerichts verhängt werden"}, {"kategorie": "", "text": "In Österreich gibt es verschiedene Arten von Strafen, die je nach Schwere der Straftat oder des Vergehens verhängt werden können: (i) [[Freiheitsstrafe]]: Der Verurteilte wird für eine bestimmte Zeit in einer Justizanstalt inhaftiert. Es gibt auch die lebenslange Freiheitsstrafe für besonders schwere Verbrechen;  (ii) [[Geldstrafe]]: Der Verurteilte muss einen bestimmten Geldbetrag an den Staat zahlen. Die Höhe richtet sich nach der Schwere der Tat und den wirtschaftlichen Verhältnissen des Täters;  (iii) [[Bedingte]] Strafen: Die Strafe kann unter bestimmten Bedingungen zur [[Bewährung]] ausgesetzt werden, das heißt, sie wird nicht sofort vollstreckt, sofern der [[Täter]] sich bewährt;  (iv) Nebenstrafen: Darunter fallen Fahrverbote, Berufsverbote oder andere Einschränkungen, die zusätzlich zur Hauptstrafe verhängt werden"}, {"kategorie": "", "text": "Die Höhe oder Dauer der Strafe hängt von verschiedenen Faktoren ab, darunter: (i) Die Schwere der Tat und deren Folgen, (ii) die Schuld des Täters, (iii)\n[[mildernde]] oder [[erschwerende]] Umstände (z. B. [[Vorstrafen]], Reue oder besondere Brutalität)"}, {"kategorie": "", "text": "Eine Strafe muss immer verhältnismäßig sein, das heißt, sie darf nicht härter sein, als es die Tat erfordert, und muss in einem gerechten Verhältnis zum begangenen Unrecht stehen. Dies wird durch die rechtlichen Prinzipien des [[Strafrechts]] und die [[Rechtsprechung]] garantiert"}, {"kategorie": "", "text": "Der Verurteilte hat das Recht, gegen eine Strafe [[Rechtsmittel]] einzulegen, wie zum Beispiel [[Berufung]] oder [[Revision]], um die Entscheidung durch ein höheres [[Gericht]] überprüfen zu lassen"}, {"kategorie": "", "text": "Wenn die Strafe rechtskräftig wird, wird sie im Rahmen des [[Strafvollzugs]] vollzogen, etwa durch Inhaftierung in einer [[Justizanstalt]] oder durch Eintreibung von [[Geldstrafen]]."}]'::jsonb, ''),
  ('schdrofaufschub', 'Schdrofaufschub', '', '', '', '', 'Strafaufschub', '[{"kategorie": "jur.", "text": "\"vorübergehende Aussetzung der Vollstreckung einer rechtskräftig verhängten [[Freiheitsstrafe]]\""}, {"kategorie": "", "text": "Der Vollzug der Strafe wird aus bestimmten rechtlichen oder humanitären Gründen für einen bestimmten Zeitraum aufgeschoben. Die [[Strafe]] bleibt jedoch bestehen und muss zu einem späteren Zeitpunkt angetreten werden"}, {"kategorie": "", "text": "Es handelt sich dabei um eine Ausnahme, die unter klar definierten Bedingungen gewährt wird, wenn es für den Verurteilten unzumutbar oder unmöglich wäre, die Strafe sofort anzutreten"}, {"kategorie": "", "text": "Der Strafaufschub ist in der [[Strafprozessordnung]] (StPO) sowie im Strafvollzugsgesetz geregelt. Er kann aus gesetzlichen, gesundheitlichen oder sozialen Gründen gewährt werden"}, {"kategorie": "", "text": "Wenn der Verurteilte schwer krank ist oder eine ärztliche Behandlung erforderlich ist, die mit der sofortigen Haftstrafe nicht vereinbar wäre, kann der Strafaufschub gewährt werden"}, {"kategorie": "", "text": "Schwangere Frauen können Aufschub erhalten, insbesondere in den letzten Monaten der Schwangerschaft oder kurz nach der Geburt"}, {"kategorie": "", "text": "Dringende persönliche oder familiäre Angelegenheiten: Dies könnte z. B. die Pflege eines schwer erkrankten Familienmitglieds betreffen oder wenn der Verurteilte wichtige wirtschaftliche oder familiäre Angelegenheiten regeln muss, bevor er die Strafe antritt"}, {"kategorie": "", "text": "Soziale oder berufliche Gründe: In Ausnahmefällen kann auch beruflichen oder wirtschaftlichen Notwendigkeiten Rechnung getragen werden"}, {"kategorie": "", "text": "Der Verurteilte oder sein Rechtsanwalt kann einen Antrag auf Strafaufschub stellen. Über den Antrag entscheidet die zuständige Strafvollstreckungsbehörde oder das Gericht, das die Strafe verhängt hat"}, {"kategorie": "", "text": "Der Strafaufschub wird in der Regel nur für einen begrenzten Zeitraum gewährt, der oft mehrere Monate, selten bis zu einem Jahr beträgt. Die genaue Dauer hängt von den Umständen des Falls ab."}]'::jsonb, ''),
  ('kaution', 'Kaution', '', '', '', '', 'Kaution', '[{"kategorie": "jur.", "text": "\"Geldsumme, die als Sicherheitsleistung hinterlegt wird, um die Erfüllung einer Verpflichtung oder die Einhaltung von Auflagen zu garantieren\""}, {"kategorie": "", "text": "Im rechtlichen Kontext, insbesondere im [[Strafprozessrecht]], dient die Kaution als [[gelinderes]] Mittel dazu, die Freilassung eines Beschuldigten aus der [[Untersuchungshaft]] zu ermöglichen, während gleichzeitig sichergestellt wird, dass der Beschuldigte im weiteren Verlauf des Verfahrens für das Gericht verfügbar bleibt und keine Fluchtgefahr besteht"}, {"kategorie": "", "text": "Die Höhe der Kaution wird vom [[Gericht]] festgelegt und richtet sich nach den persönlichen und wirtschaftlichen Verhältnissen des Beschuldigten sowie nach der Schwere der Tat. Die Summe muss einen ausreichenden Anreiz schaffen, die Verfahrenspflichten einzuhalten, darf aber nicht unangemessen hoch sein"}, {"kategorie": "", "text": "Die Kaution wird in der Regel nach Abschluss des Verfahrens zurückerstattet, wenn der Beschuldigte seinen Verpflichtungen nachgekommen ist, insbesondere wenn er zu allen Gerichtsterminen erschienen ist und keine Flucht oder Verfahrensbehinderung stattgefunden hat"}, {"kategorie": "", "text": "Verstößt der Beschuldigte gegen die Auflagen, die mit der Kaution verbunden sind, wie etwa Nichterscheinen vor Gericht oder Verletzung der Meldepflichten, kann das Gericht die Kaution einziehen. In diesem Fall geht die hinterlegte Geldsumme an den [[Staat]] verloren"}, {"kategorie": "", "text": "Die Kaution kann als Bargeld, Wertpapiere oder auch durch eine Bankgarantie hinterlegt werden. In manchen Fällen kann auch eine dritte Person die Kaution im Namen des Beschuldigten leisten"}, {"kategorie": "", "text": "Neben der finanziellen Sicherheitsleistung kann das Gericht dem Beschuldigten weitere Auflagen machen, wie z. B. die Abgabe des Reisepasses, Meldepflichten oder Kontaktverbote."}]'::jsonb, ''),
  ('geloebnis', 'Gelöbnis', '', '', '', '', 'Gelöbnis', '[{"kategorie": "jur.", "text": "\"förmliches Versprechen, das eine Person gegenüber einer Behörde oder einem [[Gericht]] abgibt, um bestimmte Verpflichtungen oder Verhaltensregeln einzuhalten\""}, {"kategorie": "", "text": "Es dient oft dazu, das Vertrauen der Behörden in die Einhaltung bestimmter Auflagen zu stärken, insbesondere im [[Strafverfahren]], wenn ein [[Beschuldigter]] oder [[Angeklagter]] anstelle einer strengeren Maßnahme (wie [[Untersuchungshaft]]) entlassen wird und sich durch das Gelöbnis zur Einhaltung von Bedingungen verpflichtet"}, {"kategorie": "", "text": "Ein Gelöbnis ist ein verbindliches und formelles Versprechen, das rechtliche Wirkung hat. Die Person erklärt sich bereit, bestimmte Auflagen oder Verhaltensweisen zu erfüllen, um z. B. von einer Untersuchungshaft verschont zu bleiben oder eine Freilassung zu erwirken"}, {"kategorie": "", "text": "Das Gelöbnis wird häufig im Zusammenhang mit der Freilassung aus der Untersuchungshaft verwendet. Der Beschuldigte verpflichtet sich dabei, bestimmte Verhaltensregeln einzuhalten, wie z. B.: (i) Meldeauflagen (regelmäßige Meldung bei den Behörden), (ii) Kontaktverbote zu bestimmten Personen, (iii) Wohnsitznahme an einem bestimmten Ort, (iv) Reisepassabgabe oder andere Maßnahmen, die verhindern sollen, dass der Beschuldigte flieht oder das Verfahren behindert"}, {"kategorie": "", "text": "Ein Gelöbnis ist rechtsverbindlich. Das bedeutet, dass derjenige, der ein Gelöbnis abgibt, rechtlich dazu verpflichtet ist, die versprochenen Verpflichtungen zu erfüllen. Bei Verstößen gegen das Gelöbnis können rechtliche Konsequenzen folgen, wie z. B. die Wiederaufnahme der Untersuchungshaft"}, {"kategorie": "", "text": "Das Gelöbnis wird oft als Teil von [[gelinderen]] Mitteln angewendet, wenn die Untersuchungshaft nicht notwendig erscheint und das Gelöbnis ausreicht, um die Verfahrensziele zu sichern. Es ist somit eine Alternative zu schwerwiegenderen Maßnahmen."}]'::jsonb, ''),
  ('schdrofprozessrecht', 'Schdrofprozessrecht', '', '', '', '', 'Strafprozessrecht', '[{"kategorie": "jur.", "text": "\"zentrales Regelwerk, welches die Verfahrensabläufe zur Ermittlung, Verfolgung, Anklage und Aburteilung von Straftaten regelt\""}, {"kategorie": "", "text": "Es umfasst alle rechtlichen Bestimmungen, die das Verfahren zwischen dem Verdacht einer Straftat und der endgültigen Entscheidung über Schuld oder Unschuld eines Angeklagten regeln"}, {"kategorie": "", "text": "Das Strafprozessrecht gliedert sich in mehrere Verfahrensabschnitte, die das gesamte Strafverfahren abdecken: (i) [[Ermittlungsverfahren]] (in diesem Abschnitt wird durch die [[Staatsanwaltschaft]] und die [[Polizei]] der Sachverhalt aufgeklärt, um festzustellen, ob ein hinreichender Tatverdacht vorliegt),  (ii) [[Hauptverfahren]] (wenn genügend Beweise vorliegen, erhebt die Staatsanwaltschaft [[Anklage]], und das Gericht verhandelt die Sache in einer [[Hauptverhandlung]], in der der Richter über Schuld oder Unschuld entscheidet,  (iii) [[Rechtsmittelverfahren]]: Nach dem Urteil besteht die Möglichkeit, [[Rechtsmittel]] (z. B. [[Berufung]] oder [[Nichtigkeitsbeschwerde]]) gegen die Entscheidung einzulegen"}, {"kategorie": "", "text": "Die wichtigsten Akteure im Strafprozessrecht sind:  (i) [[Staatsanwaltschaft]] (leitet das Ermittlungsverfahren und erhebt [[Anklage]], wenn genügend Beweise für eine Straftat vorliegen),  (ii) [[Beschuldigter]]/[[Angeklagter]] (die Person, gegen die das Verfahren geführt wird und welche während des gesamten Verfahrens Rechte wie das [[rechtliche]] Gehör, die [[Unschuldsvermutung]] und dasà Recht auf Verteidigung hat),  (iii) [[Gericht]] (ist für die Leitung des Verfahrens, die Urteilsfindung und die Verhängung von Strafen zuständig),  (iv) [[Verteidigung]] (der Beschuldigte wird in der Regel durch einen Rechtsanwalt vertreten, der seine Interessen und Rechte im Verfahren wahrt)"}, {"kategorie": "", "text": "Opfer einer Straftat können im Verfahren als [[Nebenkläger]] auftreten und haben bestimmte Rechte, wie z. B. Akteneinsicht oder Schadensersatzforderungen"}, {"kategorie": "", "text": "Das österreichische Strafprozessrecht basiert auf mehreren Grundprinzipien: (i) Legalitätsprinzip (die Staatsanwaltschaft ist verpflichtet, bei Verdacht auf eine Straftat ein Verfahren einzuleiten), (ii) Anklageprinzip (das Gericht darf nur über Straftaten entscheiden, die von der Staatsanwaltschaft angeklagt wurden), (iii) Mündlichkeit und Öffentlichkeit: (die Hauptverhandlung erfolgt mündlich und in der Regel öffentlich, um Transparenz zu gewährleisten, (iv) Verhältnismäßigkeit (Eingriffe in die Rechte des Beschuldigten, wie z. B. [[Untersuchungshaft]] oder Hausdurchsuchungen, müssen verhältnismäßig und gerechtfertigt sein)"}, {"kategorie": "", "text": "Die [[Strafprozessordnung]] (StPO) ist das zentrale Gesetz, das den Ablauf und die Regeln für das strafrechtliche Verfahren in Österreich festlegt. Sie enthält die Bestimmungen zur Einleitung eines Verfahrens, zur Durchführung der Ermittlungen und zur Hauptverhandlung sowie zu den Rechtsmitteln."}]'::jsonb, ''),
  ('bundesfinanzgericht', 'Bundesfinanzgericht', '', '', '', '', 'Bundesfinanzgericht', '[{"kategorie": "jur.", "text": "\"unabhängiges Verwaltungsgerichts, das über Streitigkeiten in Abgabensachen und Steuerangelegenheiten entscheidet\""}, {"kategorie": "", "text": "Insbesondere das Bundesfinanzgericht (BFG) ist dabei für die Überprüfung von Entscheidungen der Finanzbehörden zuständig und prüft die Rechtmäßigkeit von Steuerbescheiden und anderen Entscheidungen der [[Finanzverwaltung]] und stellt sicher, dass die Steuergesetze korrekt angewendet werden"}, {"kategorie": "", "text": "Das BFG befasst sich außerdem mit Rechtsstreitigkeiten zu Abgaben, Zöllen, Finanzstrafen sowie Angelegenheiten der Sozialversicherung im Zusammenhang mit Steuern"}, {"kategorie": "", "text": "Das Bundesfinanzgericht ist eine Rechtsmittelinstanz, an die Steuerpflichtige und Unternehmen ihre Beschwerden richten können, wenn sie mit den Entscheidungen der Finanzbehörden nicht einverstanden sind"}, {"kategorie": "", "text": "Das Verfahren vor dem Bundesfinanzgericht wird in der Regel in schriftlicher Form durchgeführt, kann aber auch eine mündliche Verhandlung umfassen, in der die Argumente der beteiligten Parteien erörtert werden.\nDas Gericht überprüft, ob die angefochtene Entscheidung rechtmäßig ist, das heißt, ob die Gesetze korrekt angewendet wurden und die Entscheidung den tatsächlichen Gegebenheiten entspricht"}, {"kategorie": "", "text": "Das Bundesfinanzgericht entscheidet durch Urteil, das entweder die Entscheidung der Finanzbehörde bestätigt, abändert oder aufhebt. Diese Entscheidungen können von den Beteiligten vor dem [[Verwaltungsgerichtshof]] (VwGH) oder dem [[Verfassungsgerichtshof]] (VfGH) weiter angefochten werden, wenn bestimmte Voraussetzungen erfüllt sind"}, {"kategorie": "", "text": "Das Bundesfinanzgericht ist eine unabhängige Behörde, die weder den Finanzbehörden noch dem Bundesministerium für Finanzen untergeordnet ist. Es handelt nach den Grundsätzen eines fairen Verfahrens und der [[Rechtsstaatlichkeit]]."}]'::jsonb, ''),
  ('finanzgericht', 'Finanzgericht', '', '', '', '', 'Finanzgericht', '[{"kategorie": "jur.", "text": "\"unabhängiges Verwaltungsgerichts, das über Streitigkeiten in Abgabensachen und Steuerangelegenheiten entscheidet\""}, {"kategorie": "", "text": "Insbesondere das Bundesfinanzgericht (BFG) ist dabei für die Überprüfung von Entscheidungen der Finanzbehörden zuständig und prüft die Rechtmäßigkeit von Steuerbescheiden und anderen Entscheidungen der [[Finanzverwaltung]] und stellt sicher, dass die Steuergesetze korrekt angewendet werden"}, {"kategorie": "", "text": "Das BFG befasst sich außerdem mit Rechtsstreitigkeiten zu Abgaben, Zöllen, Finanzstrafen sowie Angelegenheiten der Sozialversicherung im Zusammenhang mit Steuern"}, {"kategorie": "", "text": "Das Bundesfinanzgericht ist eine Rechtsmittelinstanz, an die Steuerpflichtige und Unternehmen ihre Beschwerden richten können, wenn sie mit den Entscheidungen der Finanzbehörden nicht einverstanden sind"}, {"kategorie": "", "text": "Das Verfahren vor dem Bundesfinanzgericht wird in der Regel in schriftlicher Form durchgeführt, kann aber auch eine mündliche Verhandlung umfassen, in der die Argumente der beteiligten Parteien erörtert werden.\nDas Gericht überprüft, ob die angefochtene Entscheidung rechtmäßig ist, das heißt, ob die Gesetze korrekt angewendet wurden und die Entscheidung den tatsächlichen Gegebenheiten entspricht"}, {"kategorie": "", "text": "Das Bundesfinanzgericht entscheidet durch Urteil, das entweder die Entscheidung der Finanzbehörde bestätigt, abändert oder aufhebt. Diese Entscheidungen können von den Beteiligten vor dem [[Verwaltungsgerichtshof]] (VwGH) oder dem [[Verfassungsgerichtshof]] (VfGH) weiter angefochten werden, wenn bestimmte Voraussetzungen erfüllt sind"}, {"kategorie": "", "text": "Das Bundesfinanzgericht ist eine unabhängige Behörde, die weder den Finanzbehörden noch dem Bundesministerium für Finanzen untergeordnet ist. Es handelt nach den Grundsätzen eines fairen Verfahrens und der [[Rechtsstaatlichkeit]]."}]'::jsonb, ''),
  ('finanzvawoitung', 'Finanzvawoitung', '', '', '', '', 'Finanzverwaltung', '[{"kategorie": "jur.", "text": "\"staatliches Verwaltungssystem, das für die Erhebung, Verwaltung und Überwachung von Steuern und Abgaben zuständig ist\""}, {"kategorie": "", "text": "Sie spielt eine zentrale Rolle in der Finanzpolitik des Landes und sorgt dafür, dass die gesetzlich festgelegten Steuerpflichten korrekt erfüllt und durchgesetzt werden"}, {"kategorie": "", "text": "Die Finanzverwaltung untersteht dem Bundesministerium für Finanzen (BMF) und umfasst verschiedene Behörden und Institutionen, die auf Bundes- und Landesebene tätig sind:  (i) Das BMF ist die oberste Behörde, die die Finanzverwaltung steuert und die Finanzpolitik des Landes gestaltet;  (ii) Finanzämter (diese sind in ganz Österreich verteilt und für die Abwicklung der Steuererhebung auf regionaler Ebene verantwortlich. Sie nehmen Steuererklärungen entgegen, berechnen die Steuern und wickeln Zahlungen ab),  (iii) Zollämter (neben den Finanzämtern gibt es Zollämter, die für die Erhebung von Zöllen, Einfuhrabgaben und die Überwachung des grenzüberschreitenden Warenverkehrs zuständig sind),  (iv) Abgabenbehörden (diese stellen sicher, dass alle Abgaben und Gebühren, die gesetzlich festgelegt sind, erhoben und überwacht werden)"}, {"kategorie": "", "text": "Ein wichtiger Teil der Finanzverwaltung ist die Durchführung von Betriebsprüfungen und Steuerfahndungen, um sicherzustellen, dass die Steuerpflichtigen ihre Steuerlast korrekt berechnen und entrichten. Bei Verdacht auf Steuerhinterziehung oder Steuerbetrug können umfangreiche Prüfungen eingeleitet werden"}, {"kategorie": "", "text": "Falls Steuern oder Abgaben nicht freiwillig gezahlt werden, verfügt die Finanzverwaltung über Zwangsmittel wie die Pfändung, um ausstehende Steuerforderungen zwangsweise einzutreiben"}, {"kategorie": "", "text": "Gegen Entscheidungen der Finanzämter können Steuerpflichtige vor den [[Finanzgerichten]] Einspruch erheben. Diese Gerichte sind Teil der Finanzverwaltung und prüfen die Rechtmäßigkeit von Steuerbescheiden."}]'::jsonb, ''),
  ('foalaessigkeit', 'Foalässigkeit', '', '', '', '', 'Fahrlässigkeit', '[{"kategorie": "jur.", "text": "\"Verhalten, bei dem jemand durch Sorgfaltsmangel oder Unachtsamkeit eine rechtswidrige Handlung begeht, ohne diese bewusst herbeiführen zu wollen\""}, {"kategorie": "", "text": "Im Gegensatz zum [[Vorsatz]] handelt der Täter fahrlässig, wenn er nicht die nötige Sorgfalt walten lässt, die ein vernünftiger Mensch in der gleichen Situation angewandt hätte, und dadurch ein Schaden oder eine Straftat entsteht"}, {"kategorie": "", "text": "Fahrlässigkeit ist in § 6 des Strafgesetzbuches (StGB) geregelt: \"Fahrlässig handelt, wer eine strafbare Handlung zwar nicht vorsätzlich begeht, aber nicht die erforderliche Sorgfalt anwendet, zu der er nach den Umständen und seiner persönlichen Verhältnisse verpflichtet wäre\""}, {"kategorie": "", "text": "Im Gegensatz zum Vorsatz, bei dem der Täter bewusst und gewollt eine Straftat begeht, liegt bei Fahrlässigkeit kein Wille zur Tatbegehung vor. Der Täter handelt nicht absichtlich, sondern lässt die notwendige Sorgfalt vermissen oder berücksichtigt nicht die möglichen Folgen seines Handelns"}, {"kategorie": "", "text": "Arten der Fahrlässigkeit: (i) Einfache Fahrlässigkeit (der Täter hat die Sorgfalt außer Acht gelassen, die von ihm in der jeweiligen Situation verlangt wird. Es geht um allgemeine Unachtsamkeit oder Unvorsichtigkeit),  (ii) Grobe Fahrlässigkeit (hier handelt der Täter in einem besonders hohen Maße unvorsichtig oder leichtsinnig und verletzt gravierend seine Sorgfaltspflichten, die jeder vernünftige Mensch in dieser Situation erkennen würde. Grobe Fahrlässigkeit führt in der Regel zu härteren Strafen)"}, {"kategorie": "", "text": "Nicht alle Straftaten erfordern einen Vorsatz. Es gibt Straftaten, die auch bei fahrlässiger Begehung strafbar sind. Beispiele sind: (i) Fahrlässige Körperverletzung (§ 88 StGB): Wenn jemand durch Unachtsamkeit eine andere Person verletzt;  (ii) Fahrlässige Tötung (§ 80 StGB): Wenn jemand durch fahrlässiges Verhalten den Tod eines anderen Menschen verursacht, z. B. bei einem Verkehrsunfall;  (iii) Fahrlässige Gefährdung der körperlichen Sicherheit (§ 89 StGB): Wenn jemand durch unsachgemäßes Verhalten andere Menschen in Gefahr bringt"}, {"kategorie": "", "text": "Ein zentraler Aspekt der Fahrlässigkeit ist die Sorgfaltspflicht. Das bedeutet, dass jeder Mensch in bestimmten Situationen eine gewisse Sorgfalt anwenden muss, um Schäden oder Gefahren zu vermeiden. Diese Sorgfaltspflicht variiert je nach den Umständen und kann von Berufsgruppen oder persönlichen Fähigkeiten abhängig sein"}, {"kategorie": "", "text": "Ein weiteres wichtiges Merkmal der Fahrlässigkeit ist die Vorhersehbarkeit der Tatfolgen. Fahrlässig handelt, wer die Folgen seines Verhaltens hätte vorhersehen können, aber nicht ausreichend gehandelt hat, um diese zu verhindern. Bei grober Fahrlässigkeit wird davon ausgegangen, dass die Folgen der Tat für jeden erkennbar gewesen wären."}]'::jsonb, ''),
  ('vuasotz', 'Vuasotz', '', '', '', '', 'Vorsatz', '[{"kategorie": "jur.", "text": "\"rechtlicher Begriff im [[Strafrecht]], welcher die absichtliche oder bewusste Herbeiführung einer Straftat beschreibt\""}, {"kategorie": "", "text": "Eine Person handelt mit Vorsatz, wenn sie eine Tat mit Wissen und Wollen begeht, also die Handlung und deren Folgen bewusst herbeiführt oder diese zumindest in Kauf nimmt"}, {"kategorie": "", "text": "In Österreich ist der Vorsatz in § 5 des Strafgesetzbuches (StGB) geregelt. Dort heißt es: \"Ein Täter handelt vorsätzlich, wenn er eine Tatbestandsverwirklichung will oder ernsthaft für möglich hält und sich mit dieser Möglichkeit abfindet\". Das bedeutet, dass jemand vorsätzlich handelt, wenn er die Tat bewusst begeht und die Folgen gewollt oder zumindest in Kauf genommen hat"}, {"kategorie": "", "text": "Wie in vielen Rechtssystemen unterscheidet das österreichische Strafrecht zwischen verschiedenen Formen des Vorsatzes: (i) Absichtlicher Vorsatz (der Täter hat den Willen, eine Straftat herbeizuführen. Er strebt aktiv das tatbestandsmäßige Ergebnis an - z. B. eine Person zu töten),  (ii) Direkter Vorsatz (der Täter weiß, dass sein Verhalten den Erfolg der Tat sicher oder mit hoher Wahrscheinlichkeit herbeiführen wird. Die Folge der Handlung tritt zwangsläufig ein, auch wenn der Täter sie nicht unbedingt will - z.B. in Brand gesetztes Gebäude mit Wissen, dass jemand darin ist),  (iii) Bedingter Vorsatz: Der Täter hält die Möglichkeit für gegeben, dass seine Handlung einen tatbestandsmäßigen Erfolg hat, und er nimmt diese Möglichkeit in Kauf. Hier handelt es sich nicht um eine Absicht, aber der Täter sieht den Erfolg als mögliche Konsequenz seines Handelns und ist damit einverstanden (z. B. gefährliche Handlung, die jemandem Schaden zufügen könnte)"}, {"kategorie": "", "text": "Vorsätzliche Handlungen werden im österreichischen Strafrecht in der Regel strenger bestraft als fahrlässige Taten, da der Täter bei vorsätzlichen Straftaten das Unrecht bewusst in Kauf nimmt"}, {"kategorie": "", "text": "Viele Straftaten setzen im österreichischen Strafrecht den Vorsatz voraus, um als solche geahndet zu werden (z. B. Diebstahl, Betrug, Mord). Ohne Vorsatz könnte in bestimmten Fällen nur eine fahrlässige Tat vorliegen, die mit milderen Strafen geahndet wird."}]'::jsonb, ''),
  ('oabeitslosngoeoed', 'Oabeitslosngööd', '', '', '', '', 'Arbeitslosengeld', '[{"kategorie": "jur.", "text": "\"finanzielle Unterstützung, die an Personen gezahlt wird, die ihren Arbeitsplatz verloren haben, sich aktiv um eine neue Beschäftigung bemühen und die gesetzlichen Voraussetzungen erfüllen\""}, {"kategorie": "", "text": "Es soll den Lebensunterhalt während der Arbeitslosigkeit sichern und die finanzielle Situation der Betroffenen stabilisieren, bis sie eine neue Anstellung finden"}, {"kategorie": "", "text": "Um Arbeitslosengeld zu erhalten, muss die Person arbeitslos, arbeitswillig und arbeitsfähig sein. Die Antragsteller müssen sich beim [[Arbeitsmarktservice]] (AMS) arbeitslos melden und sich aktiv um eine neue Beschäftigung bemühen"}, {"kategorie": "", "text": "Zudem müssen sie eine bestimmte Zeit lang zuvor sozialversicherungspflichtig beschäftigt gewesen sein (Anwartschaftszeit), das heißt: Innerhalb der letzten zwei Jahre mindestens 52 Wochen sozialversicherungspflichtig beschäftigt oder bei unter 25-Jährigen mindestens 26 Wochen"}, {"kategorie": "", "text": "Die Höhe des Arbeitslosengeldes beträgt in der Regel 55 % des letzten Nettoeinkommens. Zusätzlich können Familienzuschläge und andere Leistungen wie Wohn- oder Kinderzuschüsse gewährt werden, die das Einkommen der Betroffenen weiter stützen"}, {"kategorie": "", "text": "Die Bezugsdauer des Arbeitslosengeldes hängt von der Dauer der vorhergehenden Beschäftigung und dem Lebensalter des Antragstellers ab: Für Personen, die kürzer als 6 Monate gearbeitet haben, beträgt die Bezugsdauer maximal 20 Wochen. Bei längerer vorheriger Beschäftigung kann die Bezugsdauer auf bis zu 52 Wochen verlängert werden, bei älteren Personen sogar bis zu 78 Wochen"}, {"kategorie": "", "text": "Nach Ablauf des Anspruchs auf Arbeitslosengeld kann unter bestimmten Voraussetzungen [[Notstandshilfe]] beantragt werden"}, {"kategorie": "", "text": "Während des Bezugs von Arbeitslosengeld bleibt der Antragsteller krankenversichert und hat Zugang zu medizinischen Leistungen. Auch die Pensionsversicherung bleibt in dieser Zeit aufrecht, um keine Lücken im Versicherungsverlauf entstehen zu lassen."}]'::jsonb, '')
